window.SAT_DATA = window.SAT_DATA || {};
(window.SAT_DATA.vocabQuestions = window.SAT_DATA.vocabQuestions || []).push(
{"id": "vq-mh-abate", "wordId": "mh-abate", "skill": "words-in-context", "stem": "Epidemiologists tracking the 1918 influenza outbreak in rural districts noted that infection rates did not ______ until quarantine measures had been in place for several weeks: only then did daily case counts begin their steady decline.", "choices": [{"text": "escalate", "why": "Reversed: to escalate is to increase in intensity, but the colon points to a 'steady decline,' the opposite direction.", "tag": "reversed"}, {"text": "fluctuate", "why": "Unsupported: to fluctuate is to shift irregularly up and down, but the passage describes a steady one-directional decline, not variability.", "tag": "unsupported"}, {"text": "abate", "why": "The colon glosses the blank: case counts 'begin their steady decline,' so the blank must mean lessen or decrease."}, {"text": "stabilize", "why": "Fails on precision: to stabilize is to stop changing and hold level, but the counts did not level off—they declined steadily.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-mh-abolished", "wordId": "mh-abolished", "skill": "words-in-context", "stem": "In nineteenth-century Britain, imprisonment for unpaid debts was finally ______ by parliamentary statute: the once-routine practice disappeared entirely from the legal system rather than being merely narrowed or reformed.", "choices": [{"text": "abolished", "why": "The colon explains the blank: the practice 'disappeared entirely,' so the statute must have formally ended or eliminated it."}, {"text": "reinstated", "why": "Reversed: to reinstate is to restore something previously removed, but the passage says the practice vanished, not that it returned.", "tag": "reversed"}, {"text": "amended", "why": "Contradicted by the passage: to amend is to alter or reform, and the text explicitly rules out the practice 'being merely... reformed.'", "tag": "unsupported"}, {"text": "regulated", "why": "Fails on precision: to regulate is to control or restrict, but the practice was not narrowed—it was eliminated outright.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-mh-abridge", "wordId": "mh-abridge", "skill": "words-in-context", "stem": "Facing printing costs that threatened the project, the editors chose to ______ the explorer's two-thousand-page journals, trimming repetitive entries while preserving every major expedition narrative so that a single published volume retained the original's essential arc.", "choices": [{"text": "annotate", "why": "Unsupported: to annotate is to add explanatory notes, but the editors were cutting material to reduce costs, not adding commentary.", "tag": "unsupported"}, {"text": "embellish", "why": "Reversed: to embellish is to add decorative or elaborative material, the opposite of the trimming the passage describes.", "tag": "reversed"}, {"text": "censor", "why": "Wrong domain: to censor is to suppress objectionable content, but the cuts here targeted repetition for length and cost, not offensive material.", "tag": "too-specific"}, {"text": "abridge", "why": "The clues 'trimming repetitive entries while preserving' the core and fitting a 'single published volume' point to shortening the work—precisely what abridge means."}], "answer": 3},
{"id": "vq-mh-accentuate", "wordId": "mh-accentuate", "skill": "words-in-context", "stem": "Medieval mapmakers often traced coastlines in saturated indigo to ______ the boundary between land and sea: the vivid pigment drew the viewer's eye directly to the contour most critical for navigation.", "choices": [{"text": "obscure", "why": "Reversed: to obscure is to hide or make unclear, but the pigment made the boundary more visible, not less.", "tag": "reversed"}, {"text": "accentuate", "why": "The colon explains the purpose: the pigment 'drew the viewer's eye directly' to the boundary, so the blank must mean emphasize or highlight."}, {"text": "replicate", "why": "Unsupported: to replicate is to copy or reproduce, and nothing in the passage concerns duplicating the coastline.", "tag": "unsupported"}, {"text": "exaggerate", "why": "Fails on intensity: to exaggerate is to distort beyond truth, but the mapmakers made a real contour more prominent without misrepresenting it.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-mh-accessible", "wordId": "mh-accessible", "skill": "words-in-context", "stem": "Although quantum mechanics is notorious for its forbidding mathematics, the physicist's popular essays render the field's central ideas ______ to general readers: vivid analogies stand in for formal equations, so no specialized training is required.", "choices": [{"text": "esoteric", "why": "Reversed: esoteric means intelligible only to specialists, but the essays remove the need for specialized training.", "tag": "reversed"}, {"text": "indispensable", "why": "Unsupported: indispensable means absolutely necessary, and the passage discusses how easily readers can grasp the ideas, not whether they need them.", "tag": "unsupported"}, {"text": "accessible", "why": "The colon gives the clue: analogies replace equations so 'no specialized training is required,' meaning the ideas become easy for anyone to understand."}, {"text": "familiar", "why": "Fails on precision: familiar means already well known, but the essays make new ideas understandable, not previously encountered.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-acclaim", "wordId": "mh-acclaim", "skill": "words-in-context", "stem": "Zaha Hadid's design for the Vitra Fire Station drew international ______ upon its completion in 1993: critics lauded its fractured geometry as a bold rethinking of architectural form, and prestigious commissions soon followed.", "choices": [{"text": "notoriety", "why": "Wrong connotation: notoriety is fame for something bad or scandalous, but the critics' response was admiring, not disapproving.", "tag": "unsupported"}, {"text": "scrutiny", "why": "Fails on precision: scrutiny is close critical examination, which is neutral—the colon specifies that critics 'lauded' the design, not merely studied it.", "tag": "too-broad"}, {"text": "skepticism", "why": "Reversed: skepticism is doubt, but the passage shows critics praising the work and rewarding it with commissions.", "tag": "reversed"}, {"text": "acclaim", "why": "The colon supplies the clue: critics 'lauded' the design and prestigious commissions followed, so the building attracted enthusiastic public praise."}], "answer": 3},
{"id": "vq-mh-acquiesce", "wordId": "mh-acquiesce", "skill": "words-in-context", "stem": "Though the botanist privately doubted the committee's decision to reclassify the rare orchid, she chose to ______ rather than prolong a dispute she could not win, raising no objection when the revised taxonomy was formally adopted.", "choices": [{"text": "dissent", "why": "Reversed: to dissent is to voice disagreement, but she raised 'no objection' when the decision was adopted.", "tag": "reversed"}, {"text": "equivocate", "why": "Unsupported: to equivocate is to speak ambiguously to avoid commitment, but she made a clear choice to go along, not a vague one.", "tag": "unsupported"}, {"text": "concur", "why": "Fails on precision: to concur is to genuinely agree, but she 'privately doubted' the decision—she accepted it without actually agreeing.", "tag": "too-broad"}, {"text": "acquiesce", "why": "The clues 'privately doubted' yet 'raising no objection' capture acquiescence: reluctantly accepting something without protest."}], "answer": 3},
{"id": "vq-mh-adhere", "wordId": "mh-adhere", "skill": "words-in-context", "stem": "Conservators restoring the Ghent Altarpiece must ______ to protocols established by an international commission: every solvent, brushstroke, and varnish layer is specified in advance, and any deviation requires formal approval.", "choices": [{"text": "adhere", "why": "The colon explains the blank: every step 'is specified in advance' and 'any deviation requires formal approval,' so the conservators must strictly follow the protocols."}, {"text": "object", "why": "Reversed: to object to something is to oppose it, but the passage describes compliance with the protocols, not resistance.", "tag": "reversed"}, {"text": "revert", "why": "Unsupported: to revert to something is to return to an earlier state or practice, and nothing in the passage involves going back to a previous method.", "tag": "unsupported"}, {"text": "succumb", "why": "Wrong connotation: to succumb to something is to be overcome by a harmful force or pressure, but the protocols are professional rules to follow, not an overpowering threat.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-advocate", "wordId": "mh-advocate", "skill": "words-in-context", "stem": "Nineteenth-century landscape architects continued to ______ the creation of expansive public parks, arguing in lectures and civic reports that green space was essential to urban health, even though they had no authority to compel cities to act.", "choices": [{"text": "oppose", "why": "Reversed: to oppose is to argue against, but the architects argued that parks were 'essential to urban health'—a case in favor.", "tag": "reversed"}, {"text": "advocate", "why": "The participial clue 'arguing in lectures and civic reports that green space was essential' shows the architects publicly supported and promoted the parks."}, {"text": "mandate", "why": "Fails on intensity: to mandate is to officially require, but the passage states they 'had no authority to compel cities to act'—they could only urge.", "tag": "too-broad"}, {"text": "tolerate", "why": "Fails on intensity in the other direction: to tolerate is to passively allow, but the architects actively campaigned through lectures and reports.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-affecting", "wordId": "mh-affecting", "skill": "words-in-context", "stem": "Critics found the memoir's final chapters quietly ______: the author's spare, unadorned account of her father's decline moved many reviewers to tears, achieving its emotional force without a trace of melodrama.", "choices": [{"text": "detached", "why": "Reversed: detached means emotionally uninvolved, but chapters that 'moved many reviewers to tears' are the opposite of cold or distant.", "tag": "reversed"}, {"text": "sentimental", "why": "Fails on precision: sentimental implies excessive or self-indulgent emotion, which 'spare, unadorned' and 'without a trace of melodrama' explicitly rule out.", "tag": "too-broad"}, {"text": "humorous", "why": "Unsupported: humorous means comic or amusing, but the passage describes an account of decline that brought reviewers to tears, not laughter.", "tag": "unsupported"}, {"text": "affecting", "why": "The colon gives the clue: the chapters 'moved many reviewers to tears' through genuine 'emotional force,' so they were deeply touching—affecting."}], "answer": 3},
{"id": "vq-mh-affinity", "wordId": "mh-affinity", "skill": "words-in-context", "stem": "Even as a child, the marine biologist felt a deep, almost instinctive ______: she returned to the same rocky tide pools day after day, crouching for hours, drawn again and again to the small creatures she discovered among the stones.", "choices": [{"text": "affinity", "why": "The colon elaborates a natural pull—returning 'day after day,' 'drawn again and again'—so the blank names an instinctive liking or attraction."}, {"text": "aversion", "why": "Reversed: an aversion is a strong dislike that would drive her away, not draw her back repeatedly.", "tag": "reversed"}, {"text": "rapport", "why": "Rapport is a harmonious mutual understanding between people; it does not describe a person's pull toward a place or wild creatures.", "tag": "unsupported"}, {"text": "detachment", "why": "Reversed: detachment is emotional distance or indifference, the opposite of the eager, repeated engagement described.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-allude", "wordId": "mh-allude", "skill": "words-in-context", "stem": "Rather than naming the war directly, the poet chose only to ______ to it, scattering images of broken fences and empty chairs through the verses so that readers would sense the loss without ever being told of it outright.", "choices": [{"text": "refer", "why": "To refer is to mention openly and by name, but the poet deliberately avoids naming the war 'directly.'", "tag": "unsupported"}, {"text": "attest", "why": "Reversed: to attest is to affirm or bear witness openly, the opposite of hinting at something indirectly.", "tag": "reversed"}, {"text": "object", "why": "To object is to voice disapproval, a stance the passage never suggests the poet takes.", "tag": "unsupported"}, {"text": "allude", "why": "'Rather than naming... directly' and conveying loss 'without ever being told outright' describe hinting at something indirectly."}], "answer": 3},
{"id": "vq-mh-ambiguous", "wordId": "mh-ambiguous", "skill": "words-in-context", "stem": "The treaty's crucial final clause proved hopelessly ______: one delegation read it as a binding commitment to disarm at once, while the other insisted it required nothing more than a promise of future talks.", "choices": [{"text": "ambiguous", "why": "The colon shows two conflicting yet defensible readings of one clause, so it admits more than one meaning."}, {"text": "unequivocal", "why": "Reversed: unequivocal means leaving no doubt and allowing only one interpretation, the opposite of yielding two readings.", "tag": "reversed"}, {"text": "obscure", "why": "Obscure means murky or hard to perceive, but each side reads the clause plainly and confidently—just differently.", "tag": "unsupported"}, {"text": "verbose", "why": "Verbose means using too many words; the problem is dual meaning, not length.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-ambivalence", "wordId": "mh-ambivalence", "skill": "words-in-context", "stem": "Offered a prestigious research post overseas, Mara was seized by ______: thrilled at the honor and eager to prove herself, she nonetheless dreaded leaving the crowded, familiar city and the friends who had shaped her.", "choices": [{"text": "elation", "why": "Elation names intense joy alone, ignoring the dread she simultaneously feels.", "tag": "too-specific"}, {"text": "ambivalence", "why": "'Thrilled... nonetheless dreaded' names two opposing feelings held at once—the core of ambivalence."}, {"text": "indifference", "why": "Reversed: indifference is an absence of feeling, contradicting her strong reactions on both sides.", "tag": "reversed"}, {"text": "reluctance", "why": "Reluctance captures only her dread, not the thrill and eagerness she feels at the same time.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-ameliorate", "wordId": "mh-ameliorate", "skill": "words-in-context", "stem": "The sanitation commission's reforms were designed not to abolish urban poverty outright but to ______ the daily hardships of tenement dwellers; cleaner water and better ventilation made cramped, difficult lives at least somewhat more bearable.", "choices": [{"text": "aggravate", "why": "Reversed: to aggravate is to make a bad situation worse, but the reforms make lives 'more bearable.'", "tag": "reversed"}, {"text": "eradicate", "why": "To eradicate is to wipe out completely, which the passage explicitly says the reforms were 'not' meant to do to poverty.", "tag": "too-specific"}, {"text": "ameliorate", "why": "Making hardships 'at least somewhat more bearable' is making a bad situation better without removing it."}, {"text": "chronicle", "why": "To chronicle is to record events; it concerns documenting, not improving, conditions.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-amorphous", "wordId": "mh-amorphous", "skill": "words-in-context", "stem": "Before the sculptor imposed any structure on it, the wet clay remained utterly ______, its surface bulging and sagging without a single edge, plane, or discernible form to give it definition.", "choices": [{"text": "symmetrical", "why": "Reversed: symmetrical means evenly and regularly shaped, contradicting a mass with no form at all.", "tag": "reversed"}, {"text": "nebulous", "why": "Nebulous means hazy or vague and suits ideas or mist, not a solid clay mass with a definite physical surface.", "tag": "too-specific"}, {"text": "angular", "why": "Reversed: angular means marked by sharp corners and edges, which the phrase 'without a single edge' rules out.", "tag": "reversed"}, {"text": "amorphous", "why": "'Without a single edge, plane, or discernible form' and a surface that merely bulges and sags describe something shapeless."}], "answer": 3},
{"id": "vq-mh-analogous", "wordId": "mh-analogous", "skill": "words-in-context", "stem": "The biologist argued that a bird's wing and an insect's wing, though built from entirely different tissues, are functionally ______: each independently evolved the same solution, a broad surface generating lift, to the shared problem of flight.", "choices": [{"text": "analogous", "why": "Arriving at 'the same solution... for flight' from different starting tissues makes the two wings comparable in function."}, {"text": "identical", "why": "Identical means exactly alike, contradicted by 'entirely different tissues.'", "tag": "too-specific"}, {"text": "antithetical", "why": "Reversed: antithetical means directly opposed, the opposite of similar or comparable.", "tag": "reversed"}, {"text": "arbitrary", "why": "Arbitrary means based on whim rather than reason, which has nothing to do with the wings' likeness in function.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-annotate", "wordId": "mh-annotate", "skill": "words-in-context", "stem": "As she prepared the medieval manuscript for its first printed edition, the scholar took care to ______ it thoroughly, adding marginal notes that clarified obscure terms and traced every quotation back to its original source.", "choices": [{"text": "annotate", "why": "'Adding marginal notes that clarified obscure terms' and traced sources is precisely making explanatory notes on a text."}, {"text": "transcribe", "why": "To transcribe is to copy a text out word for word, which adds no explanatory notes of one's own.", "tag": "too-specific"}, {"text": "censor", "why": "Reversed: to censor is to remove objectionable content, the opposite of enriching the text with added notes.", "tag": "reversed"}, {"text": "abridge", "why": "To abridge is to condense or shorten a text, whereas she is adding material to it.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-anomalous", "wordId": "mh-anomalous", "skill": "words-in-context", "stem": "For weeks the readings had held perfectly steady, so when the seismograph traced a single ______ spike, unlike anything the instrument had registered before or since, the researchers first suspected a malfunction rather than a genuine tremor.", "choices": [{"text": "predictable", "why": "Reversed: predictable means regular and expected, but the spike is 'unlike anything' recorded before.", "tag": "reversed"}, {"text": "anomalous", "why": "A spike 'unlike anything the instrument had registered before or since,' amid steady readings, deviates from the norm."}, {"text": "erratic", "why": "Erratic means irregular and inconsistent over time, but the passage describes one isolated spike, not ongoing unpredictability.", "tag": "too-specific"}, {"text": "recurrent", "why": "Reversed: recurrent means happening again and again, contradicting 'a single' spike seen neither before nor since.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-appease", "wordId": "mh-appease", "skill": "words-in-context", "stem": "Hoping to ______ the restive frontier nobles, the young king granted them tax exemptions and seats on his royal council; the concessions bought a fragile peace that lasted nearly a decade.", "choices": [{"text": "appease", "why": "The king offers concessions and the result is 'a fragile peace,' so the blank must mean pacify or satisfy the discontented nobles."}, {"text": "provoke", "why": "Reversed: to provoke is to stir up anger or rebellion, the opposite of what concessions that 'bought a fragile peace' would do.", "tag": "reversed"}, {"text": "suppress", "why": "To suppress is to put down by force or authority, but the king used generous concessions, not coercion, to calm the nobles.", "tag": "unsupported"}, {"text": "emulate", "why": "To emulate is to imitate in hopes of matching someone; nothing suggests the king wanted to copy the nobles rather than calm them.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-applaud", "wordId": "mh-applaud", "skill": "words-in-context", "stem": "Reviewers rushed to ______ the architect's design for the city's new library, citing its daylight-filled reading rooms and its deference to the surrounding historic district as proof that civic buildings can be at once practical and inspiring.", "choices": [{"text": "condemn", "why": "Reversed: to condemn is to denounce strongly, but the reviewers cite the design's virtues as 'proof' of its success.", "tag": "reversed"}, {"text": "applaud", "why": "The reviewers point to the design's merits as proof that it is 'practical and inspiring,' so the blank must mean praise enthusiastically."}, {"text": "tolerate", "why": "Wrong intensity: to tolerate is to put up with something grudgingly, far weaker than the enthusiastic endorsement the reviewers' 'proof' language conveys.", "tag": "too-specific"}, {"text": "scrutinize", "why": "To scrutinize is to examine closely and neutrally, but the reviewers have already reached an emphatically favorable verdict.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-applicable", "wordId": "mh-applicable", "skill": "words-in-context", "stem": "Though the mathematical model was devised to describe how vehicles merge on crowded highways, its equations proved equally ______ to pedestrian movement: stadium planners now use the same formulas to design exits that ease congestion after large events.", "choices": [{"text": "identical", "why": "Too broad a claim: the same formulas are used, but calling the equations 'identical to pedestrian movement' overstates and misstates the relationship, which is one of relevance, not sameness.", "tag": "too-broad"}, {"text": "irrelevant", "why": "Reversed: the colon shows planners actually use the formulas for pedestrians, so the model is pertinent, not beside the point.", "tag": "reversed"}, {"text": "applicable", "why": "The colon explains that planners 'use the same formulas' for crowds, showing the model is relevant to—can be applied to—the new domain."}, {"text": "detrimental", "why": "Detrimental means harmful; the passage says the formulas 'ease congestion,' describing a benefit, not damage.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-appraising", "wordId": "mh-appraising", "skill": "words-in-context", "stem": "Before the museum could insure the newly donated canvas, specialists spent weeks ______ it—comparing its brushwork with authenticated works, testing pigment samples, and consulting auction records to fix a defensible estimate of its worth.", "choices": [{"text": "restoring", "why": "Restoring means repairing to a former condition, but the activities listed are all forms of examination and valuation, not repair.", "tag": "unsupported"}, {"text": "discarding", "why": "Reversed: discarding means throwing away as worthless, yet the museum is preparing to insure the canvas and establish its value.", "tag": "reversed"}, {"text": "admiring", "why": "Admiring means regarding with aesthetic pleasure; the passage describes a systematic, evidence-based valuation, not appreciation.", "tag": "unsupported"}, {"text": "appraising", "why": "The dash introduces the methods used 'to fix a defensible estimate of its worth,' the defining activity of appraising—assessing value."}], "answer": 3},
{"id": "vq-mh-apprehend", "wordId": "mh-apprehend", "skill": "words-in-context", "stem": "The composer's private notation is so idiosyncratic that even devoted scholars admit they cannot fully ______ his intentions: entire passages of the late quartets remain open to sharply conflicting interpretations.", "choices": [{"text": "apprehend", "why": "The colon shows that his intentions cannot be settled—interpretations conflict—so the blank must mean grasp or understand."}, {"text": "transcribe", "why": "Too narrow: transcribing is copying notation into another form, but the difficulty described is understanding meaning, not recopying symbols.", "tag": "too-specific"}, {"text": "dismiss", "why": "Reversed: to dismiss is to reject as unworthy of attention, yet these 'devoted scholars' are laboring to understand the works, not brush them aside.", "tag": "reversed"}, {"text": "endorse", "why": "To endorse is to declare approval; the passage concerns comprehension of the composer's intentions, and approval is never at issue.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-apprentice", "wordId": "mh-apprentice", "skill": "words-in-context", "stem": "Workshop ledgers from Renaissance Florence reveal that most painters began not as independent masters but as ______: adolescents bound to a senior artist for years of grinding pigments, preparing panels, and copying drawings before accepting commissions of their own.", "choices": [{"text": "patrons", "why": "Reversed role: a patron commissions and finances art, but the passage describes beginners performing menial tasks to learn the craft.", "tag": "reversed"}, {"text": "apprentices", "why": "The colon defines the role—young people 'bound to a senior artist' for years of training tasks—which is precisely what an apprentice is."}, {"text": "connoisseurs", "why": "A connoisseur is an expert judge of quality; that implies refined mastery, contradicting adolescents still learning to grind pigments.", "tag": "unsupported"}, {"text": "rivals", "why": "A rival is a competitor, but the relationship described is instruction and service under a master, not competition with one.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-arcane", "wordId": "mh-arcane", "skill": "words-in-context", "stem": "The treatises of medieval alchemists are notoriously ______: written in invented symbols and deliberately coded language, they were intelligible only to initiated practitioners and continue to resist confident interpretation by modern scholars.", "choices": [{"text": "accessible", "why": "Reversed: accessible means easily understood, but the texts were 'intelligible only to initiated practitioners' and still baffle scholars.", "tag": "reversed"}, {"text": "arcane", "why": "The colon explains that the texts were coded so that only initiates could read them—known to few and mysterious, the core meaning of arcane."}, {"text": "obsolete", "why": "The treatises are indeed old, but obsolete means outdated and no longer useful, which does not explain why only initiates could read them.", "tag": "true-but-irrelevant"}, {"text": "verbose", "why": "Verbose means using too many words; the difficulty described is deliberate secrecy and coding, not wordiness.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-arduous", "wordId": "mh-arduous", "skill": "words-in-context", "stem": "The nineteenth-century survey of the Andes proved ______: crews hauled fragile instruments over unmapped passes, endured weeks of freezing storms, and re-measured entire baselines by hand whenever landslides destroyed their markers.", "choices": [{"text": "futile", "why": "Futile means producing no result; the passage shows the work was punishing, but nothing indicates the survey failed or was pointless.", "tag": "unsupported"}, {"text": "monotonous", "why": "Too narrow: monotonous means dull through sameness, but hauling instruments over unmapped passes amid storms describes strain and danger, not boredom.", "tag": "too-specific"}, {"text": "arduous", "why": "The colon lists grueling physical demands—hauling, enduring storms, re-measuring by hand—so the blank must mean extremely difficult and strenuous."}, {"text": "lucrative", "why": "Lucrative means highly profitable; the passage says nothing about money, only about the labor the survey required.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-assent", "wordId": "mh-assent", "skill": "words-in-context", "stem": "Under the 1867 confederation scheme, no amendment to the colonial charter could take effect until every provincial delegation had granted its formal ______; a single delegation's refusal, however grudging, was enough to stall reform for years.", "choices": [{"text": "dissent", "why": "Reversed: dissent means disagreement, which is what the contrasting clause about \"refusal\" describes, not what the charter requires delegations to grant.", "tag": "reversed"}, {"text": "assent", "why": "The semicolon contrasts the blank with \"refusal,\" so the blank must mean agreement or approval—what each delegation must grant for an amendment to take effect."}, {"text": "acclaim", "why": "Too strong: acclaim is enthusiastic public praise, but the charter requires only approval, which the passage suggests could even be given grudgingly.", "tag": "too-broad"}, {"text": "scrutiny", "why": "Scrutiny is close, critical examination; the passage concerns authorization of amendments, not their inspection.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-assertive", "wordId": "mh-assertive", "skill": "words-in-context", "stem": "Whereas her predecessor rarely voiced objections during negotiations, the new ambassador adopted an ______ approach, stating her government's positions plainly and pressing counterparts for direct answers while still maintaining a courteous, professional tone.", "choices": [{"text": "acquiescent", "why": "Reversed: acquiescent means passively accepting without protest, which matches the timid predecessor, not the ambassador who presses for answers.", "tag": "reversed"}, {"text": "aggressive", "why": "Too strong: aggressive implies hostility or combativeness, which the \"courteous, professional tone\" explicitly rules out.", "tag": "too-broad"}, {"text": "obstinate", "why": "Obstinate means stubbornly refusing to change one's position; the passage describes plain, confident speaking, not inflexibility.", "tag": "unsupported"}, {"text": "assertive", "why": "The contrast with a predecessor who \"rarely voiced objections,\" plus \"stating positions plainly\" while staying courteous, defines a confident, self-assured style."}], "answer": 3},
{"id": "vq-mh-attest", "wordId": "mh-attest", "skill": "words-in-context", "stem": "Charred grain stores, loom weights, and dozens of clay seals unearthed at the site ______ to a thriving textile economy: such artifacts could only have accumulated where weaving and trade were sustained for generations.", "choices": [{"text": "attest", "why": "The colon explains that the artifacts \"could only have accumulated\" under sustained weaving and trade, so they serve as evidence that confirms the economy existed."}, {"text": "allude", "why": "Too weak: to allude is to hint at something indirectly, but the passage presents the artifacts as decisive proof, not a vague suggestion.", "tag": "too-specific"}, {"text": "object", "why": "Reversed: to object to something is to express opposition to it, the opposite of providing supporting evidence.", "tag": "reversed"}, {"text": "succumb", "why": "To succumb is to yield to an overpowering force or temptation; artifacts confirming a historical claim have nothing to do with surrender.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-attrition", "wordId": "mh-attrition", "skill": "words-in-context", "stem": "Rather than collapsing after any single crisis, the rural school district was weakened by steady ______: every year a few more veteran teachers resigned than the district could replace, until entire departments had quietly hollowed out.", "choices": [{"text": "exodus", "why": "Wrong pace: an exodus is a sudden mass departure, but the passage stresses gradual, year-by-year losses rather than one dramatic event.", "tag": "too-broad"}, {"text": "attrition", "why": "The colon defines the blank—staff numbers gradually shrinking as resignations outpace replacements—which is precisely attrition, a slow reduction or weakening."}, {"text": "recruitment", "why": "Reversed: recruitment is the gaining of new staff, the opposite of the steady losses that hollowed out departments.", "tag": "reversed"}, {"text": "stagnation", "why": "Stagnation means standing still without change, but the district is actively shrinking, not merely failing to grow.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-augment", "wordId": "mh-augment", "skill": "words-in-context", "stem": "Because the provincial museum's permanent holdings were too sparse to fill its new wing, curators negotiated long-term loans from private collectors to ______ the collection without straining the acquisition budget.", "choices": [{"text": "curtail", "why": "Reversed: to curtail is to cut back, but holdings \"too sparse to fill\" the wing need expansion, not reduction.", "tag": "reversed"}, {"text": "supplant", "why": "To supplant is to replace something entirely; the borrowed works are added alongside the permanent holdings, not substituted for them.", "tag": "unsupported"}, {"text": "appraise", "why": "To appraise is to assess the monetary value of something; the passage concerns enlarging the collection, not valuing it.", "tag": "unsupported"}, {"text": "augment", "why": "The clue \"too sparse to fill its new wing\" shows the collection needs enlarging, and loans that add works without new purchases augment—increase—it."}], "answer": 3},
{"id": "vq-mh-barricade", "wordId": "mh-barricade", "skill": "words-in-context", "stem": "During the 1848 uprising in Paris, insurgents tore up paving stones and overturned carts to assemble a makeshift ______ across the boulevard, a hastily piled obstruction that halted cavalry charges for nearly two days.", "choices": [{"text": "rampart", "why": "Wrong register: a rampart is a permanent defensive embankment built into a fortification, not an improvised pile of stones and carts blocking a street.", "tag": "too-specific"}, {"text": "thoroughfare", "why": "Reversed: a thoroughfare is a route for passage, the opposite of an obstruction that halts movement.", "tag": "reversed"}, {"text": "garrison", "why": "A garrison is a body of troops stationed in a town, not a physical structure that can be piled up from stones and carts.", "tag": "unsupported"}, {"text": "barricade", "why": "The appositive \"a hastily piled obstruction that halted cavalry charges\" defines the blank as a makeshift barrier blocking the street."}], "answer": 3},
{"id": "vq-mh-belie", "wordId": "mh-belie", "skill": "words-in-context", "stem": "The essayist's breezy, conversational prose ______ the labor behind it: drafts in her archive reveal that each seemingly offhand paragraph was rewritten a dozen times over several months.", "choices": [{"text": "belies", "why": "The colon exposes a contrast between appearance and reality—effortless-seeming prose masking painstaking revision—so the blank must mean gives a false impression of."}, {"text": "betrays", "why": "Reversed: to betray a feeling or fact is to inadvertently reveal it, but the breezy prose hides the labor rather than exposing it.", "tag": "reversed"}, {"text": "commemorates", "why": "To commemorate is to honor the memory of something; the prose conceals the revision process rather than celebrating it.", "tag": "unsupported"}, {"text": "epitomizes", "why": "To epitomize is to be a perfect example of something, but casual-seeming prose is not an example of heavy labor—it misrepresents it.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-benevolent", "wordId": "mh-benevolent", "skill": "words-in-context", "stem": "Contemporaries regarded the industrialist as unusually ______: at his own expense he built workers' housing with running water, endowed a hospital and schools, and provided pensions decades before the law required any such provision.", "choices": [{"text": "shrewd", "why": "Shrewd means clever and calculating in practical matters; the passage catalogs voluntary generosity, not business cunning.", "tag": "unsupported"}, {"text": "lenient", "why": "Too narrow: lenient means mild in punishing or enforcing rules, but the acts described are charitable gifts, not relaxed discipline.", "tag": "too-specific"}, {"text": "benevolent", "why": "The colon lists charitable acts performed \"at his own expense\" and beyond legal obligation, marking the industrialist as kind and generous."}, {"text": "ostentatious", "why": "Ostentatious means showy in order to impress; nothing in the passage suggests the motive was display rather than workers' welfare.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-biased", "wordId": "mh-biased", "skill": "words-in-context", "stem": "Reviewers rejected the study's conclusions about national reading habits as ______, noting that the researchers had surveyed only affluent urban households and had therefore given one segment of the population disproportionate weight.", "choices": [{"text": "comprehensive", "why": "Reversed: comprehensive means covering everything, but the survey's flaw is that it covered only one narrow slice of the population.", "tag": "reversed"}, {"text": "biased", "why": "Surveying \"only affluent urban households\" and giving one group \"disproportionate weight\" describes an unfair tilt toward one segment—precisely what biased means."}, {"text": "subjective", "why": "Subjective means based on personal feelings rather than evidence; the flaw described is a skewed sample, not reliance on opinion.", "tag": "unsupported"}, {"text": "obsolete", "why": "Obsolete means out of date; the passage says nothing about the study's timing or its methods being superseded.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-breadth", "wordId": "mh-breadth", "skill": "words-in-context", "stem": "Critics were struck less by the anthology's insight into any single tradition than by its ______: the volume gathers poems from five continents, spans eight centuries, and moves among dozens of forms and dialects.", "choices": [{"text": "brevity", "why": "Reversed: brevity means shortness, but the colon emphasizes how expansively the volume ranges across places, eras, and forms.", "tag": "reversed"}, {"text": "depth", "why": "Precision failure: depth is thorough treatment of a single area, which the passage explicitly sets aside with \"less by... any single tradition.\"", "tag": "too-specific"}, {"text": "breadth", "why": "The colon catalogs range—five continents, eight centuries, dozens of forms—so the blank must mean wide extent or scope."}, {"text": "novelty", "why": "Novelty means newness or originality; the critics praise the collection's range, not its inventiveness.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-buttress", "wordId": "mh-buttress", "skill": "words-in-context", "stem": "A historian studying ancient trade gathered pottery fragments, coins, and shipwreck records to ______ her claim that two distant civilizations had maintained regular contact; each new artifact added weight to a thesis that skeptical colleagues had once dismissed outright.", "choices": [{"text": "buttress", "why": "The clue that each artifact 'added weight' to a once-dismissed thesis signals that the evidence is meant to support and strengthen the claim."}, {"text": "undermine", "why": "Reversed direction: to undermine is to weaken, but the artifacts reinforce the claim.", "tag": "reversed"}, {"text": "embellish", "why": "To embellish is to add decorative or exaggerated detail; the passage describes strengthening a claim with evidence, not ornamenting it.", "tag": "unsupported"}, {"text": "summarize", "why": "To summarize is merely to condense; it says nothing about lending support, which the accumulating evidence does.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-mh-bypass", "wordId": "mh-bypass", "skill": "words-in-context", "stem": "To reduce delays at the crowded central interchange, city planners designed a ring road that would ______ the downtown core entirely, allowing freight trucks to reach the port without ever entering the congested grid of streets.", "choices": [{"text": "traverse", "why": "Reversed: to traverse is to pass directly through, but the road is meant to route trucks around the core.", "tag": "reversed"}, {"text": "bypass", "why": "The phrase 'without ever entering the congested grid' shows the road is built to go around and avoid the downtown core."}, {"text": "obstruct", "why": "To obstruct is to block; the plan clears a path rather than blocking one, contradicting the goal.", "tag": "unsupported"}, {"text": "monitor", "why": "To monitor is to observe; the road routes traffic around the center, not watch over it.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-capacious", "wordId": "mh-capacious", "skill": "words-in-context", "stem": "When the new wing of the natural history museum opened, curators marveled at how ______ its central hall was: the vaulted space could hold a reconstructed whale skeleton, a suspended aircraft, and hundreds of visitors at once without ever feeling crowded.", "choices": [{"text": "lofty", "why": "Too narrow: lofty refers to height alone, but the clue emphasizes the hall's total holding capacity, not merely its tallness.", "tag": "too-specific"}, {"text": "cramped", "why": "Reversed: cramped means confined and short of space, the opposite of a hall that never feels crowded.", "tag": "reversed"}, {"text": "capacious", "why": "The detail that the hall holds huge objects and hundreds of people 'without feeling crowded' points to a space that is roomy and spacious."}, {"text": "ornate", "why": "Ornate describes lavish decoration, not size; the passage is concerned with how much the hall can hold.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-captivate", "wordId": "mh-captivate", "skill": "words-in-context", "stem": "From her very first note, the young cellist seemed to ______ the entire concert hall; listeners sat motionless and utterly absorbed, unwilling even to shift in their seats until the final chord had faded into silence.", "choices": [{"text": "amuse", "why": "Too weak: to amuse is to provide mild diversion, not the rapt, spellbound absorption the audience displays.", "tag": "too-broad"}, {"text": "bore", "why": "Reversed: to bore is to make listless, but the listeners are riveted and enthralled.", "tag": "reversed"}, {"text": "unsettle", "why": "To unsettle is to make uneasy; the audience is entranced, not disturbed.", "tag": "unsupported"}, {"text": "captivate", "why": "The image of motionless, utterly absorbed listeners shows the cellist charms and mesmerizes the hall."}], "answer": 3},
{"id": "vq-mh-catalyst", "wordId": "mh-catalyst", "skill": "words-in-context", "stem": "Historians often point to the assassination as the ______ for the wider conflict: although tensions had simmered for decades, that single event set in motion the alliances and mobilizations that plunged the continent into war.", "choices": [{"text": "aftermath", "why": "Reversed: an aftermath is a consequence that follows, but the event is described as what set the war in motion.", "tag": "reversed"}, {"text": "catalyst", "why": "The phrase 'set in motion' the events leading to war identifies the assassination as the trigger that precipitated the conflict."}, {"text": "precedent", "why": "A precedent is an earlier case that guides later ones; nothing suggests the event served as a model, only that it ignited the war.", "tag": "unsupported"}, {"text": "hindrance", "why": "A hindrance impedes; the assassination advances the conflict rather than obstructing it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-circumspection", "wordId": "mh-circumspection", "skill": "words-in-context", "stem": "The veteran diplomat was known for her ______: before responding to any proposal she weighed every possible consequence, consulted her advisers, and chose her words so deliberately that opponents could rarely find fault with them.", "choices": [{"text": "impulsiveness", "why": "Reversed: impulsiveness is acting hastily without reflection, the opposite of weighing every consequence beforehand.", "tag": "reversed"}, {"text": "eloquence", "why": "Eloquence is fluent, persuasive speech; the passage stresses careful deliberation before speaking, not verbal polish itself.", "tag": "unsupported"}, {"text": "circumspection", "why": "Weighing every consequence and choosing words with great care before acting describes caution and carefulness exactly."}, {"text": "vigilance", "why": "Too narrow: vigilance is watchful alertness to danger, whereas the passage describes deliberative caution before acting.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-clumsily", "wordId": "mh-clumsily", "skill": "words-in-context", "stem": "The novelist portrays the nervous apprentice ______ fumbling with the delicate instruments, dropping one tool after another and knocking a glass beaker from the bench as his trembling hands refused to cooperate.", "choices": [{"text": "gracefully", "why": "Reversed: gracefully means with ease and elegance, contradicting the fumbling and dropping the passage describes.", "tag": "reversed"}, {"text": "deliberately", "why": "To act deliberately is to act on purpose, but the mishaps stem from trembling, uncontrolled hands, not intention.", "tag": "unsupported"}, {"text": "hastily", "why": "Too narrow: hastily stresses speed, but the passage emphasizes gracelessness and lack of control, not how fast he moves.", "tag": "too-specific"}, {"text": "clumsily", "why": "Fumbling, dropping tools, and knocking over a beaker with uncooperative hands is the very picture of acting awkwardly and ungracefully."}], "answer": 3},
{"id": "vq-mh-coalesce", "wordId": "mh-coalesce", "skill": "words-in-context", "stem": "Over millions of years, the scattered particles of dust and gas orbiting the young star began to ______, gradually drawing together under the pull of gravity until they formed the solid cores of the first planets.", "choices": [{"text": "coalesce", "why": "Particles 'drawing together' under gravity to form planetary cores describes them uniting and combining into a single mass."}, {"text": "disperse", "why": "Reversed: to disperse is to scatter apart, the opposite of drawing together into planets.", "tag": "reversed"}, {"text": "condense", "why": "Too narrow: to condense is to grow denser or turn from gas to liquid, not to merge separate particles into larger bodies.", "tag": "too-specific"}, {"text": "fluctuate", "why": "To fluctuate is to shift back and forth irregularly; the passage describes steady merging, not variation.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-cohesion", "wordId": "mh-cohesion", "skill": "words-in-context", "stem": "After the new captain introduced shared goals and open communication, the once-fractured squad developed a striking sense of ______: players trusted one another, moved as a single unit, and no longer pursued personal glory at the team's expense.", "choices": [{"text": "rivalry", "why": "Reversed: rivalry is internal competition and conflict, the opposite of players who now trust each other and move as one.", "tag": "reversed"}, {"text": "cohesion", "why": "Mutual trust and players 'moving as a single unit' rather than seeking personal glory captures unity and solidarity."}, {"text": "conformity", "why": "Too narrow: conformity is uniformity of behavior or compliance, not the mutual bonding and shared purpose the passage describes.", "tag": "too-specific"}, {"text": "hierarchy", "why": "A hierarchy is a system of ranking; the passage concerns unity among equals, not a chain of authority.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-coincidental", "wordId": "mh-coincidental", "skill": "words-in-context", "stem": "The researchers cautioned that the apparent link between the two rising trends was probably ______: with so many variables tracked over the decade, some pairs were bound to rise together by chance alone, with no real connection between them.", "choices": [{"text": "deliberate", "why": "Reversed: deliberate means intentional, but the passage attributes the link to random chance, not design.", "tag": "reversed"}, {"text": "causal", "why": "Reversed: causal implies one trend truly produces the other, the very connection the researchers say is absent.", "tag": "reversed"}, {"text": "coincidental", "why": "The explanation that the pairing arose 'by chance alone, with no real connection' matches something accidental and unplanned."}, {"text": "anomalous", "why": "Anomalous means abnormal or deviating; the passage says such chance pairings are expected, not unusual.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-concur", "wordId": "mh-concur", "skill": "words-in-context", "stem": "When an independent panel re-examined the disputed safety report, the reviewers found the engineer's warnings so thoroughly documented that they could only ______: every member accepted her conclusion that the existing measures were inadequate.", "choices": [{"text": "concur", "why": "The clause 'every member accepted her conclusion' signals unanimous agreement, so the blank must mean to agree or accord."}, {"text": "demur", "why": "To demur is to raise objections or hesitate, the reverse of the unanimous acceptance the passage describes.", "tag": "reversed"}, {"text": "waver", "why": "To waver is to be indecisive, but the reviewers are said to accept the conclusion firmly.", "tag": "unsupported"}, {"text": "digress", "why": "To digress is to wander off topic, which has nothing to do with the reviewers' shared verdict.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-confine", "wordId": "mh-confine", "skill": "words-in-context", "stem": "Early ecologists assumed the rare orchid could flourish almost anywhere, but later fieldwork showed that its dependence on a single soil fungus forced botanists to ______ their search to the few shaded ravines where that fungus actually thrives.", "choices": [{"text": "broaden", "why": "To broaden is to widen the scope, the opposite of narrowing the search to a few ravines.", "tag": "reversed"}, {"text": "confine", "why": "'To the few shaded ravines where that fungus thrives' narrows the range, so the blank must mean to restrict or limit."}, {"text": "catalogue", "why": "To catalogue is to list systematically; the sentence is about restricting where they look, not recording it.", "tag": "unsupported"}, {"text": "relinquish", "why": "To relinquish is to give up entirely, but the botanists continue searching in a smaller area.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-conflate", "wordId": "mh-conflate", "skill": "words-in-context", "stem": "A recurring error in introductory reasoning is to treat two distinct relationships as though they were a single one; students who ______ correlation and causation assume that because two trends happen to rise together, one of them must be producing the other.", "choices": [{"text": "distinguish", "why": "To distinguish is to tell things apart, the opposite of treating them as a single relationship.", "tag": "reversed"}, {"text": "isolate", "why": "To isolate is to set one thing apart from others, again the reverse of merging the two concepts.", "tag": "reversed"}, {"text": "quantify", "why": "To quantify is to measure in numbers, which is unrelated to blurring two ideas together.", "tag": "unsupported"}, {"text": "conflate", "why": "'Treat two distinct relationships as though they were a single one' defines the blank as to merge or confuse them."}], "answer": 3},
{"id": "vq-mh-conjecture", "wordId": "mh-conjecture", "skill": "words-in-context", "stem": "The astronomer was careful to label her proposal precisely: lacking any direct observation of the distant planet's interior, she presented her account of its composition as ______, a plausible guess awaiting the measurements a future probe might one day supply.", "choices": [{"text": "certainty", "why": "Certainty implies established fact, but the astronomer explicitly lacks direct observation.", "tag": "reversed"}, {"text": "conjecture", "why": "'A plausible guess awaiting measurements' and 'lacking any direct observation' define the blank as speculation or a guess."}, {"text": "consensus", "why": "Consensus means broad agreement among people, which the passage never mentions.", "tag": "unsupported"}, {"text": "corroboration", "why": "Corroboration is confirming evidence, the reverse of an unverified guess.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-considerate", "wordId": "mh-considerate", "skill": "words-in-context", "stem": "Unlike his brusque predecessor, the new supervisor was unfailingly ______: he learned each employee's personal constraints, adjusted deadlines whenever someone faced a family emergency, and asked after their well-being before handing out any new assignment.", "choices": [{"text": "considerate", "why": "Learning employees' constraints and asking after their well-being shows the supervisor is thoughtful and attentive to others."}, {"text": "indifferent", "why": "Indifferent means uncaring, the reverse of a supervisor attentive to each person's needs.", "tag": "reversed"}, {"text": "gregarious", "why": "Gregarious means sociable and fond of company, which is not the same as being caring toward others.", "tag": "unsupported"}, {"text": "meticulous", "why": "Meticulous describes careful attention to detail in work, not kindness toward people.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-mh-contentious", "wordId": "mh-contentious", "skill": "words-in-context", "stem": "Few issues divide the town council so sharply; the plan to reroute the highway through the old district proved deeply ______, igniting weeks of heated hearings in which neighbors who had once agreed on everything found themselves bitterly opposed.", "choices": [{"text": "contentious", "why": "'Divide the council so sharply,' 'heated hearings,' and 'bitterly opposed' mark the plan as controversial and disputed."}, {"text": "unanimous", "why": "Unanimous means agreed on by all, the opposite of a plan that sets neighbors bitterly against one another.", "tag": "reversed"}, {"text": "tedious", "why": "Tedious means tiresome or dull, but the hearings are described as heated, not boring.", "tag": "unsupported"}, {"text": "provisional", "why": "Provisional means temporary or subject to change, which says nothing about the conflict the plan provokes.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-contrivance-of", "wordId": "mh-contrivance-of", "skill": "words-in-context", "stem": "The detective revealed that the supposed haunting was no accident of nature but the deliberate ______ a scheming heir, who had secretly rigged the creaking doors and staged the ghostly noises to frighten his relatives into fleeing the estate.", "choices": [{"text": "oversight of", "why": "An oversight is a careless error, but 'deliberate' and 'secretly rigged' point to intention, not accident.", "tag": "reversed"}, {"text": "misfortune of", "why": "A misfortune is bad luck, the opposite of a plan the heir purposely engineered.", "tag": "reversed"}, {"text": "consequence of", "why": "A consequence is a mere result; the passage stresses that the haunting was purposely designed.", "tag": "unsupported"}, {"text": "contrivance of", "why": "'Deliberate,' 'rigged the doors,' and 'staged the noises' define the haunting as a scheme or invention devised by the heir."}], "answer": 3},
{"id": "vq-mh-collude", "wordId": "mh-collude", "skill": "words-in-context", "stem": "Regulators grew suspicious when the sealed bids submitted by rival construction firms proved nearly identical: rather than competing, the companies had apparently chosen to ______, quietly coordinating their offers so that each would win a predetermined share of the public contracts.", "choices": [{"text": "collude", "why": "The clues 'quietly coordinating' and dividing contracts into a 'predetermined share' describe a secret, illicit conspiracy, which is exactly what collude means."}, {"text": "collaborate", "why": "Collaborate means to work jointly, but it lacks the secretive, fraudulent connotation the passage stresses ('quietly,' rigged shares); open cooperation would not alarm regulators.", "tag": "too-broad"}, {"text": "compete", "why": "Compete means to strive against rivals, but the passage explicitly says the firms acted 'rather than competing.'", "tag": "reversed"}, {"text": "negotiate", "why": "Negotiate means to bargain openly toward an agreement, but nothing here involves open dealing; the coordination is concealed and improper.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-compensate", "wordId": "mh-compensate", "skill": "words-in-context", "stem": "When one kidney is removed, the remaining organ often grows larger and filters more blood to ______ for the loss, allowing many patients to maintain nearly normal function with a single working kidney.", "choices": [{"text": "atrophy", "why": "Atrophy means to waste away from disuse, but the remaining kidney enlarges and works harder.", "tag": "reversed"}, {"text": "deteriorate", "why": "Deteriorate means to decline in quality or function, the opposite of maintaining nearly normal function.", "tag": "reversed"}, {"text": "substitute", "why": "Substitute means to replace one thing wholesale with another, but the kidney offsets a shortfall rather than swapping in for a whole organ.", "tag": "too-broad"}, {"text": "compensate", "why": "The organ 'grows larger and filters more' to make up for the missing kidney and keep function normal, which is exactly to compensate."}], "answer": 3},
{"id": "vq-mh-complacency", "wordId": "mh-complacency", "skill": "words-in-context", "stem": "Having dominated the market for decades, the once-innovative manufacturer let ______ set in: convinced that no rival could ever threaten its position, it stopped investing in new designs and was blindsided when nimbler competitors seized its customers.", "choices": [{"text": "complacency", "why": "Being 'convinced that no rival could threaten' it and therefore ceasing to innovate is textbook complacency—smug self-satisfaction that breeds inaction."}, {"text": "trepidation", "why": "Trepidation means nervous fear, but the firm was overconfident, not anxious.", "tag": "reversed"}, {"text": "hubris", "why": "Hubris is arrogant overpride leading to reckless overreach, whereas the passage stresses passive self-satisfaction and inaction, not prideful ambition.", "tag": "too-specific"}, {"text": "diligence", "why": "Diligence is sustained careful effort, the opposite of the firm's slackening and failure to keep investing.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-compound", "wordId": "mh-compound", "skill": "words-in-context", "stem": "The region's water shortage was already severe, and a series of policy missteps only served to ______ it: subsidies encouraged farmers to plant thirsty crops, and leaking infrastructure wasted much of what little remained, deepening a crisis that sound planning might have eased.", "choices": [{"text": "alleviate", "why": "Alleviate means to ease or lessen, but the missteps deepened the crisis rather than relieving it.", "tag": "reversed"}, {"text": "resolve", "why": "Resolve means to settle or solve, the opposite of worsening the shortage.", "tag": "reversed"}, {"text": "provoke", "why": "Provoke means to trigger or bring something into being, but the shortage already existed; the missteps intensified it rather than initiating it.", "tag": "too-broad"}, {"text": "compound", "why": "The missteps 'only served to' worsen an already severe shortage, 'deepening a crisis'—precisely to compound a problem."}], "answer": 3},
{"id": "vq-mh-concede", "wordId": "mh-concede", "skill": "words-in-context", "stem": "For years the theorist defended his model against every objection, but as the experimental results piled up against him, he was finally forced to ______ that his rival's account explained the data more accurately than his own ever had.", "choices": [{"text": "insist", "why": "Insist means to assert firmly and persistently, but the passage shows him reluctantly giving ground under mounting evidence.", "tag": "reversed"}, {"text": "presume", "why": "Presume means to suppose without proof, whereas he acknowledges a conclusion the accumulated evidence forced on him.", "tag": "unsupported"}, {"text": "concede", "why": "After years of resistance he was 'finally forced to' admit his rival was right—a reluctant acknowledgment, which is what concede means."}, {"text": "contend", "why": "Contend means to argue or assert in a dispute, but he is yielding the dispute, not pressing his side of it.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-conceivable", "wordId": "mh-conceivable", "skill": "words-in-context", "stem": "Before the first exoplanets were detected, some astronomers doubted that worlds beyond our solar system could ever be found; today, with thousands catalogued, it seems entirely ______ that at least one of them harbors the conditions necessary for life.", "choices": [{"text": "unthinkable", "why": "Unthinkable means impossible even to imagine, the opposite of what the abundant evidence now makes easy to entertain.", "tag": "reversed"}, {"text": "feasible", "why": "Feasible means capable of being carried out, which applies to achievable actions or plans rather than to a fact being imaginable or possible.", "tag": "too-specific"}, {"text": "mandatory", "why": "Mandatory means required or compulsory, which concerns obligation, not possibility.", "tag": "unsupported"}, {"text": "conceivable", "why": "With thousands of exoplanets now found, it is easily imaginable that one supports life—exactly what conceivable means."}], "answer": 3},
{"id": "vq-mh-convene", "wordId": "mh-convene", "skill": "words-in-context", "stem": "According to the colony's charter, the governor could not resolve any grievance on his own; instead, whenever a serious dispute arose among the settlers, he was obliged to ______ the general assembly so that the elected representatives could deliberate and vote together.", "choices": [{"text": "disperse", "why": "Means to scatter or send away, the opposite of calling a body together.", "tag": "reversed"}, {"text": "convene", "why": "'So that the elected representatives could deliberate and vote together' signals calling the assembly into session."}, {"text": "adjourn", "why": "Means to bring a meeting to a close, not to summon one into being.", "tag": "reversed"}, {"text": "mobilize", "why": "Means to marshal people or resources for action, not to gather a body for formal deliberation.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-convergence", "wordId": "mh-convergence", "skill": "words-in-context", "stem": "Biologists studying unrelated species on separate continents were struck by an unexpected ______: wings had emerged independently in insects, birds, and bats, three lineages that never shared a common winged ancestor yet arrived at strikingly similar solutions to the problem of flight.", "choices": [{"text": "divergence", "why": "Means a moving apart or growing difference, the opposite of the shared outcome described.", "tag": "reversed"}, {"text": "fragmentation", "why": "Means a breaking into separate pieces, contrary to distinct lineages arriving at the same trait.", "tag": "reversed"}, {"text": "convergence", "why": "The colon elaborates independent lineages 'arriving at strikingly similar solutions,' meeting at the same point."}, {"text": "proliferation", "why": "Means a rapid increase in number, which the passage never mentions.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-coordinated", "wordId": "mh-coordinated", "skill": "words-in-context", "stem": "Learning from the chaos of earlier disasters, the agency's new protocol required every responding group to share a single timetable and communication channel, so that in the next emergency the arrival of medical teams, food, and shelter would be tightly ______ rather than left to chance.", "choices": [{"text": "fragmented", "why": "Means broken into disconnected parts, the opposite of arrivals meshing on one timetable.", "tag": "reversed"}, {"text": "improvised", "why": "Means made up on the spot; that is the 'left to chance' outcome the protocol is designed to prevent.", "tag": "reversed"}, {"text": "streamlined", "why": "Means made more efficient, but efficiency alone does not capture the mutual synchronization of separate groups.", "tag": "too-broad"}, {"text": "coordinated", "why": "Sharing 'a single timetable and communication channel' so arrivals mesh signals synchronized, jointly organized action."}], "answer": 3},
{"id": "vq-mh-copious", "wordId": "mh-copious", "skill": "words-in-context", "stem": "During her decade in the rainforest, the naturalist filled shelf after shelf with field journals; her ______ records of birdcalls, rainfall, and flowering times were so extensive that later researchers drew on them for generations.", "choices": [{"text": "copious", "why": "'Shelf after shelf' and 'so extensive' establish an abundant, plentiful quantity."}, {"text": "meager", "why": "Means scanty or insufficient, the opposite of the vast quantity described.", "tag": "reversed"}, {"text": "cursory", "why": "Means hasty and superficial, contradicting records detailed enough to serve later researchers for generations.", "tag": "reversed"}, {"text": "lavish", "why": "Means abundant but with connotations of luxury or extravagance, the wrong register for austere scientific notes.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-mh-counteract", "wordId": "mh-counteract", "skill": "words-in-context", "stem": "Excess carbon dioxide in the sealed greenhouse was acidifying the irrigation water, so the engineers introduced a mineral buffer designed to ______ the growing acidity and hold the water's chemistry near neutral.", "choices": [{"text": "aggravate", "why": "Means to make worse, the opposite of the corrective effect intended.", "tag": "reversed"}, {"text": "reinforce", "why": "Means to strengthen; the buffer is meant to oppose the acidity, not intensify it.", "tag": "reversed"}, {"text": "mitigate", "why": "Means to lessen severity in general, but the passage describes an opposing agent that actively neutralizes the acidity.", "tag": "too-broad"}, {"text": "counteract", "why": "A buffer that opposes 'the growing acidity' to hold the chemistry 'near neutral' acts to neutralize and offset it."}], "answer": 3},
{"id": "vq-mh-counterbalance", "wordId": "mh-counterbalance", "skill": "words-in-context", "stem": "The fund managers built the portfolio so that its two halves moved in opposite directions: when technology holdings fell, energy holdings tended to rise, and the gains in one sector would ______ the losses in the other, keeping the total value roughly steady.", "choices": [{"text": "counterbalance", "why": "Gains in one sector offsetting losses in another 'to keep the total value roughly steady' is the equalizing action."}, {"text": "exacerbate", "why": "Means to worsen, which would deepen the losses rather than steady the total.", "tag": "reversed"}, {"text": "supplement", "why": "Means to add to something, increasing a total rather than offsetting an opposing movement to hold it level.", "tag": "too-broad"}, {"text": "destabilize", "why": "Means to upset equilibrium, the opposite of the steadiness the design achieves.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-culpability", "wordId": "mh-culpability", "skill": "words-in-context", "stem": "The tribunal's task was not to measure damages but to assign responsibility: after months of testimony about falsified safety reports, the judges had to determine the firm's ______ for a collapse that its own executives had knowingly risked.", "choices": [{"text": "innocence", "why": "Means freedom from blame, the opposite of the responsibility the judges must assign.", "tag": "reversed"}, {"text": "immunity", "why": "Means exemption from penalty or legal consequence, not a measure of blameworthiness.", "tag": "unsupported"}, {"text": "culpability", "why": "Assigning 'responsibility' for a disaster executives 'knowingly risked' is a determination of guilt or blame."}, {"text": "negligence", "why": "Means fault arising from carelessness, but the passage describes deliberate, knowing risk, a broader blameworthiness than mere inattention.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-curtail", "wordId": "mh-curtail", "skill": "words-in-context", "stem": "Facing a sharp drop in tax revenue, the city council voted to ______ its after-school programs, trimming their hours and shrinking their budgets, though members insisted the services would be scaled back only temporarily rather than ended for good.", "choices": [{"text": "expand", "why": "Means to enlarge, the opposite of the reduction described.", "tag": "reversed"}, {"text": "prolong", "why": "Means to extend in duration, whereas the council is cutting hours, not lengthening them.", "tag": "reversed"}, {"text": "abolish", "why": "Means to eliminate entirely, but the passage says the programs are only scaled back, 'rather than ended for good.'", "tag": "too-specific"}, {"text": "curtail", "why": "'Trimming their hours and shrinking their budgets' and being scaled back signal reducing or cutting back."}], "answer": 3},
{"id": "vq-mh-dearth", "wordId": "mh-dearth", "skill": "words-in-context", "stem": "Historians studying the early medieval economy face a persistent obstacle: a ______ of written records from the period, since so few documents survived that scholars must reconstruct daily life largely from scattered archaeological fragments.", "choices": [{"text": "dearth", "why": "The clue 'so few documents survived' establishes an absence, so the blank must name a shortage."}, {"text": "surfeit", "why": "Reversed: a surfeit is an excessive supply, the opposite of the scarcity the passage describes.", "tag": "reversed"}, {"text": "repository", "why": "Unsupported: a repository is a storehouse of items, implying records exist rather than are missing.", "tag": "unsupported"}, {"text": "compendium", "why": "Unsupported: a compendium is a concise collection, which again implies abundance, not lack.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-decisiveness", "wordId": "mh-decisiveness", "skill": "words-in-context", "stem": "Emergency responders are trained to act with ______: hesitation during a crisis can cost lives, so leaders must commit to a clear course of action and issue firm orders without delay.", "choices": [{"text": "candor", "why": "Unsupported: candor is frankness or honesty, unrelated to acting quickly under pressure.", "tag": "unsupported"}, {"text": "empathy", "why": "True but irrelevant: empathy may help responders but is not the quality of firm, immediate action described.", "tag": "true-but-irrelevant"}, {"text": "prudence", "why": "Too broad: prudence stresses caution, yet the passage praises committing without delay rather than being careful.", "tag": "too-broad"}, {"text": "decisiveness", "why": "'Commit to a clear course of action... without delay,' set against 'hesitation,' names firm resolve."}], "answer": 3},
{"id": "vq-mh-decry", "wordId": "mh-decry", "skill": "words-in-context", "stem": "Prominent critics did not hesitate to ______ the museum's decision to sell part of its collection, publicly condemning the sale as a betrayal of the institution's duty to preserve art for the public.", "choices": [{"text": "decry", "why": "'Publicly condemning the sale as a betrayal' matches decry, to denounce openly."}, {"text": "endorse", "why": "Reversed: to endorse is to approve or support, the opposite of condemning the decision.", "tag": "reversed"}, {"text": "overlook", "why": "Unsupported: to overlook is to fail to notice, but the critics clearly noticed and reacted.", "tag": "unsupported"}, {"text": "appraise", "why": "Too broad: to appraise is to assess neutrally, lacking the condemnation the passage requires.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-mh-deferred-to", "wordId": "mh-deferred-to", "skill": "words-in-context", "stem": "Although the junior architect had strong opinions about the design, she ______ the senior partner's judgment on structural matters, trusting his decades of experience over her own untested instincts.", "choices": [{"text": "departed from", "why": "Reversed: to depart from a judgment is to go against it, contradicting her trust in his experience.", "tag": "reversed"}, {"text": "presided over", "why": "Unsupported: to preside over is to be in charge, illogical for a junior yielding to a senior.", "tag": "unsupported"}, {"text": "deferred to", "why": "'Trusting his decades of experience over her own instincts' shows she yielded to his authority."}, {"text": "elaborated on", "why": "Unsupported: to elaborate on is to add detail, not to submit to another's judgment.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-deficient", "wordId": "mh-deficient", "skill": "words-in-context", "stem": "Analysis of the overworked farmland showed that its soil was ______ in nitrogen: crops planted there grew stunted and pale because the essential nutrient was present in far too small a quantity to sustain healthy growth.", "choices": [{"text": "saturated", "why": "Reversed: saturated means fully soaked or loaded with, the opposite of a nutrient in short supply.", "tag": "reversed"}, {"text": "abundant", "why": "Reversed: abundant means plentiful, contradicting 'far too small a quantity.'", "tag": "reversed"}, {"text": "uniform", "why": "Unsupported: uniform means evenly consistent, unrelated to how much nitrogen is present.", "tag": "unsupported"}, {"text": "deficient", "why": "'Present in far too small a quantity to sustain growth' defines a lacking, insufficient supply."}], "answer": 3},
{"id": "vq-mh-defy", "wordId": "mh-defy", "skill": "words-in-context", "stem": "The gyroscope's behavior seems to ______ common intuition: rather than toppling over as one expects, the rapidly spinning wheel resists the pull of gravity and remains stubbornly upright on its narrow pivot.", "choices": [{"text": "defy", "why": "'Resists the pull of gravity... rather than toppling as one expects' matches defy, to resist or challenge."}, {"text": "confirm", "why": "Reversed: to confirm intuition is to bear it out, opposite of the wheel behaving unexpectedly.", "tag": "reversed"}, {"text": "illustrate", "why": "Unsupported: to illustrate intuition would be to demonstrate it, but the gyroscope contradicts expectation.", "tag": "unsupported"}, {"text": "exceed", "why": "Unsupported: to exceed means to surpass a limit, the wrong relationship to 'intuition.'", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-deliberate", "wordId": "mh-deliberate", "skill": "words-in-context", "stem": "The novelist's fragmented chronology is no accident but a ______ choice: she scrambles the timeline on purpose, forcing readers to piece events together and thereby mirroring her narrator's faulty memory.", "choices": [{"text": "haphazard", "why": "Reversed: haphazard means random or careless, contradicting 'no accident.'", "tag": "reversed"}, {"text": "deliberate", "why": "'No accident... on purpose' signals an intentional, calculated choice."}, {"text": "conventional", "why": "Unsupported: conventional means ordinary or traditional, but a scrambled timeline is unusual.", "tag": "unsupported"}, {"text": "reluctant", "why": "Unsupported: reluctant means unwilling, which the confident, purposeful author is not.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-demarcate", "wordId": "mh-demarcate", "skill": "words-in-context", "stem": "The treaty's surveyors were sent to ______ the new border, driving stone markers into the ground at regular intervals so that each nation would know precisely where its territory began and ended.", "choices": [{"text": "traverse", "why": "Unsupported: to traverse is to travel across, not to mark where a territory begins and ends.", "tag": "unsupported"}, {"text": "populate", "why": "Unsupported: to populate is to fill with inhabitants, unrelated to setting boundary markers.", "tag": "unsupported"}, {"text": "demarcate", "why": "'Driving markers... where its territory began and ended' matches demarcate, to mark boundaries."}, {"text": "contest", "why": "Reversed: to contest is to dispute, but the treaty settled rather than disputed the border.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-denote", "wordId": "mh-denote", "skill": "words-in-context", "stem": "On the geologist's map, different colors ______ distinct rock types: a band of deep blue, for instance, stands for limestone, while red marks the regions built from volcanic basalt.", "choices": [{"text": "obscure", "why": "Reversed: to obscure is to hide or make unclear, opposite of colors that stand for rock types.", "tag": "reversed"}, {"text": "generate", "why": "Unsupported: to generate is to produce, but map colors represent rock rather than create it.", "tag": "unsupported"}, {"text": "exaggerate", "why": "Unsupported: to exaggerate is to overstate, unrelated to symbolic representation.", "tag": "unsupported"}, {"text": "denote", "why": "'Stands for limestone... marks regions of basalt' matches denote, to indicate or represent."}], "answer": 3},
{"id": "vq-mh-designate", "wordId": "mh-designate", "skill": "words-in-context", "stem": "After years of debate, the zoning board finally voted to ______ the abandoned textile mill a protected historic site, a status that legally shields the century-old building from demolition and obligates any owner to preserve its original facade.", "choices": [{"text": "designate", "why": "The board formally confers an official status ('a protected historic site'), which is exactly what it means to designate something."}, {"text": "nominate", "why": "To put something forward as a candidate for selection; but the board grants the status outright rather than merely proposing it for later approval.", "tag": "too-specific"}, {"text": "appraise", "why": "To assess the monetary value of something, which is unrelated to conferring a protective legal status.", "tag": "unsupported"}, {"text": "demolish", "why": "To tear a structure down—the direct opposite of an action that 'shields the building from demolition.'", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-designation", "wordId": "mh-designation", "skill": "words-in-context", "stem": "For decades the small nocturnal primate was lumped together with its larger relatives, but once genetic analysis exposed deep evolutionary differences, taxonomists granted the animal its own ______ as a distinct species.", "choices": [{"text": "lineage", "why": "A line of descent or ancestry; it describes where an organism comes from, not the formal category that is 'granted' to it.", "tag": "too-specific"}, {"text": "designation", "why": "The phrase 'its own ___ as a distinct species' calls for a formal classification or title, which is precisely a designation."}, {"text": "habitat", "why": "The environment in which an organism lives, which has nothing to do with assigning a taxonomic category.", "tag": "unsupported"}, {"text": "temperament", "why": "An animal's characteristic disposition or mood; the passage concerns classification, not behavior.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-desultory", "wordId": "mh-desultory", "skill": "words-in-context", "stem": "Unlike scholars who pursue a single question for years, the young essayist read in a thoroughly ______ manner, drifting from botany to medieval warfare to naval history with no plan whatsoever connecting one book to the next.", "choices": [{"text": "methodical", "why": "Orderly and systematic—the opposite of the planless drifting the passage describes.", "tag": "reversed"}, {"text": "reluctant", "why": "Unwilling or hesitant; nothing suggests the essayist resists reading, only that his reading lacks direction.", "tag": "unsupported"}, {"text": "desultory", "why": "'Drifting... with no plan whatsoever connecting one book to the next' signals reading that is aimless and random."}, {"text": "leisurely", "why": "Unhurried and relaxed; it describes pace, but the passage stresses the absence of a guiding plan, not slowness.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-mh-deterrent", "wordId": "mh-deterrent", "skill": "words-in-context", "stem": "Farmers in the arid region long relied on the plant's bitter, foul-tasting sap as a natural ______, since grazing animals quickly learned to avoid the crop and left the ripening fields entirely untouched.", "choices": [{"text": "deterrent", "why": "Something animals 'learned to avoid' so they leave the fields alone is exactly a discouragement or obstacle to their grazing."}, {"text": "incentive", "why": "Something that encourages an action; this reverses the sense, since the sap discourages rather than invites grazing.", "tag": "reversed"}, {"text": "fertilizer", "why": "A substance added to enrich soil; the sap repels animals rather than nourishing plants.", "tag": "unsupported"}, {"text": "barrier", "why": "A physical obstruction; the sap works by taste, discouraging animals rather than physically blocking their access.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-mh-diffusion", "wordId": "mh-diffusion", "skill": "words-in-context", "stem": "Historians of technology often trace the ______ of the printing press across early modern Europe, mapping how the invention traveled from one commercial hub to the next until working presses operated in nearly every major town.", "choices": [{"text": "suppression", "why": "A deliberate holding back or stifling—the opposite of the invention's outward movement described here.", "tag": "reversed"}, {"text": "invention", "why": "The original act of creating the press; but the passage tracks how it later spread, not how it was first made.", "tag": "true-but-irrelevant"}, {"text": "restoration", "why": "The act of returning something to an earlier condition, which has no bearing on a new technology's spread.", "tag": "unsupported"}, {"text": "diffusion", "why": "The press 'traveled from one hub to the next until... every major town' describes its spread and distribution across a region."}], "answer": 3},
{"id": "vq-mh-discerning", "wordId": "mh-discerning", "skill": "words-in-context", "stem": "Only a truly ______ listener would notice that the orchestra had quietly transposed the passage upward by a single half step; to nearly everyone else in the hall, the performance sounded identical to the familiar recording.", "choices": [{"text": "distracted", "why": "Inattentive and unfocused—the opposite of the sharp attention needed to catch so subtle a change.", "tag": "reversed"}, {"text": "amateur", "why": "Inexperienced and untrained; this reverses the sense, since detecting the shift requires refined perception.", "tag": "reversed"}, {"text": "opinionated", "why": "Holding strong views; having opinions is unrelated to the acute perception the passage requires.", "tag": "too-broad"}, {"text": "discerning", "why": "Catching a subtlety that 'nearly everyone else' misses signals a keenly perceptive, discriminating listener."}], "answer": 3},
{"id": "vq-mh-discrepancy", "wordId": "mh-discrepancy", "skill": "words-in-context", "stem": "When the auditor set the company's two ledgers side by side, she immediately flagged a troubling ______: the sum recorded as deposited each month never once matched the total the bank claimed to have received.", "choices": [{"text": "consensus", "why": "General agreement—the opposite of figures that 'never once matched.'", "tag": "reversed"}, {"text": "surplus", "why": "An excess quantity; but the problem is that the numbers conflict, not that there is extra money.", "tag": "too-specific"}, {"text": "discrepancy", "why": "Two totals that 'never once matched' are exactly an inconsistency or difference between the records."}, {"text": "correlation", "why": "A mutual relationship in which figures move together; the passage stresses that the numbers fail to align.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-distrust", "wordId": "mh-distrust", "skill": "words-in-context", "stem": "After the corporation repeatedly concealed the environmental damage caused by its factories, residents of the surrounding towns came to regard every subsequent press release with deep ______, assuming that each new assurance merely masked further deception.", "choices": [{"text": "distrust", "why": "The clue that residents assume every assurance 'masked further deception' signals suspicion of the company's honesty, the exact meaning of distrust."}, {"text": "reverence", "why": "Reverence means deep respect or awe, the opposite of the wary suspicion the betrayed residents feel.", "tag": "reversed"}, {"text": "curiosity", "why": "Curiosity is a desire to learn or know more; the passage describes suspicion of deceit, not interest.", "tag": "unsupported"}, {"text": "resentment", "why": "Resentment names bitterness or anger at unfair treatment; it is tempting after a betrayal but does not capture the specific idea of doubting the truth of the assurances.", "tag": "true-but-irrelevant"}], "answer": 0},
{"id": "vq-mh-divisive", "wordId": "mh-divisive", "skill": "words-in-context", "stem": "The proposed rezoning ordinance proved deeply ______: neighbors who had cooperated for years suddenly split into rival factions, each convinced the other was betraying the community's future.", "choices": [{"text": "divisive", "why": "The colon's elaboration, that neighbors 'split into rival factions,' defines the blank as something that drives people into opposing groups, which is what divisive means."}, {"text": "unifying", "why": "Unifying means bringing people together, the opposite of splitting a community into factions.", "tag": "reversed"}, {"text": "provocative", "why": "Provocative means tending to stir up strong feeling; it is tempting but describes arousing reaction generally, not the specific splitting into opposing sides.", "tag": "too-broad"}, {"text": "conciliatory", "why": "Conciliatory means intended to reconcile or appease, which contradicts a measure that turns neighbors into rivals.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-dwindling", "wordId": "mh-dwindling", "skill": "words-in-context", "stem": "Each season the glacier's ______ ice reserves supplied less meltwater to the valley below, forcing farmers to abandon the very fields their families had irrigated for generations.", "choices": [{"text": "swelling", "why": "Swelling means growing larger, the opposite of reserves that supply steadily less water.", "tag": "reversed"}, {"text": "dwindling", "why": "The reserves 'supplied less meltwater' each season until farmers had to abandon their fields, showing a steady decrease, which is what dwindling means."}, {"text": "stagnating", "why": "Stagnating means ceasing to develop while staying the same; the passage describes an ongoing decline, not a static level.", "tag": "unsupported"}, {"text": "fluctuating", "why": "Fluctuating means rising and falling irregularly; it is tempting but the passage shows a consistent downward trend, not variation.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-mh-ebb", "wordId": "mh-ebb", "skill": "words-in-context", "stem": "As the expedition dragged into its third fruitless month, the crew felt their initial excitement steadily ______, replaced by a weary indifference to whether they ever reached the summit at all.", "choices": [{"text": "surge", "why": "Surge means to rise suddenly and powerfully, the reverse of enthusiasm giving way to weary indifference.", "tag": "reversed"}, {"text": "intensify", "why": "Intensify means to grow stronger, contradicting excitement that is 'replaced by' indifference.", "tag": "reversed"}, {"text": "ebb", "why": "The excitement is 'steadily... replaced by a weary indifference,' signaling a gradual fading, which is exactly what ebb means."}, {"text": "waver", "why": "Waver means to fluctuate or hesitate; it is tempting but implies wobbling back and forth rather than the steady decline the passage describes.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-mh-eccentric", "wordId": "mh-eccentric", "skill": "words-in-context", "stem": "Neighbors traded stories about the old inventor's ______ habits: he kept every clock in his house set to a time zone of his own devising and delivered nightly lectures to the pigeons that gathered on his windowsill.", "choices": [{"text": "conventional", "why": "Conventional means ordinary and conforming to custom, the opposite of the strange behavior the passage catalogs.", "tag": "reversed"}, {"text": "meticulous", "why": "Meticulous means extremely careful and precise; it does not capture the oddness of inventing a private time zone or lecturing pigeons.", "tag": "true-but-irrelevant"}, {"text": "reclusive", "why": "Reclusive means avoiding the company of others; the passage shows peculiar habits rather than a withdrawal from society.", "tag": "unsupported"}, {"text": "eccentric", "why": "The examples of a self-invented time zone and lectures to pigeons illustrate unconventional, peculiar behavior, which is what eccentric means."}], "answer": 3},
{"id": "vq-mh-eliciting", "wordId": "mh-eliciting", "skill": "words-in-context", "stem": "Skilled oral historians excel at ______ candid memories from reluctant interviewees, gently phrasing each question so that even painful recollections rise to the surface without the speaker ever feeling interrogated.", "choices": [{"text": "suppressing", "why": "Suppressing means holding back or stifling, the opposite of drawing memories to the surface.", "tag": "reversed"}, {"text": "eliciting", "why": "The historians phrase questions so that memories 'rise to the surface,' meaning they draw out those recollections, which is what eliciting means."}, {"text": "cataloguing", "why": "Cataloguing means systematically listing already-gathered material; the passage concerns coaxing memories out, not organizing them.", "tag": "unsupported"}, {"text": "embellishing", "why": "Embellishing means adding invented or decorative detail; that would distort the 'candid' memories the historians want to obtain.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-elusive", "wordId": "mh-elusive", "skill": "words-in-context", "stem": "For decades the subatomic particle proved maddeningly ______: theorists were certain it existed, yet every experiment designed to capture direct evidence of it came up empty.", "choices": [{"text": "conspicuous", "why": "Conspicuous means highly visible and obvious, the reverse of a particle no experiment can detect.", "tag": "reversed"}, {"text": "abundant", "why": "Abundant means present in great quantity and easily found, contradicting the repeated failure to capture any evidence.", "tag": "reversed"}, {"text": "elusive", "why": "The particle exists yet 'every experiment... came up empty,' showing it is difficult to find or pin down, which is what elusive means."}, {"text": "hypothetical", "why": "Hypothetical means existing only in theory; it is tempting but the passage says theorists were 'certain it existed,' so the problem is detection, not existence.", "tag": "true-but-irrelevant"}], "answer": 2},
{"id": "vq-mh-embellished", "wordId": "mh-embellished", "skill": "words-in-context", "stem": "Rather than recounting the shipwreck plainly, the old sailor ______ each retelling with towering waves and monstrous beasts, until the modest squall of his youth had swelled into a full-blown epic ordeal.", "choices": [{"text": "condensed", "why": "Condensed means shortened or compressed, the opposite of a story that grows more elaborate with each telling.", "tag": "reversed"}, {"text": "exaggerated", "why": "Exaggerated means overstated in magnitude; it is tempting but the 'retelling with towering waves and monstrous beasts' points to adding decorative invented detail, the sense captured by the correct word.", "tag": "too-specific"}, {"text": "authenticated", "why": "Authenticated means verified as genuine, the opposite of dressing up a modest event with invented flourishes.", "tag": "unsupported"}, {"text": "embellished", "why": "The sailor adorns each retelling 'with towering waves and monstrous beasts,' adding colorful and invented detail, which is exactly what embellished means."}], "answer": 3},
{"id": "vq-mh-disguise", "wordId": "mh-disguise", "skill": "words-in-context", "stem": "To evade predators, the leaf-tailed gecko can flatten its body and adjust its coloring to ______ itself as a patch of dead bark, becoming so convincing that even sharp-eyed birds pass over it as they scan the tree trunk for a meal.", "choices": [{"text": "disguise", "why": "The clue 'as a patch of dead bark' and 'so convincing... pass over it' shows the gecko alters its appearance to pass as something else, which is exactly what disguise means."}, {"text": "advertise", "why": "Reversed: advertise means to draw attention to something, the opposite of hiding from birds.", "tag": "reversed"}, {"text": "obscure", "why": "Too broad: obscure means to make dim or unclear, but the passage describes actively impersonating dead bark, not merely blurring itself.", "tag": "too-broad"}, {"text": "dislodge", "why": "Unsupported: dislodge means to knock something loose from a fixed position, which has nothing to do with the gecko's appearance.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-dismissal", "wordId": "mh-dismissal", "skill": "words-in-context", "stem": "The abrupt ______ of the newspaper's veteran editor, announced one morning without any stated reason, stunned the entire staff; within a week, several reporters had walked out in protest of the leadership's decision to force her out.", "choices": [{"text": "promotion", "why": "Reversed: promotion means an advancement in rank, but the editor was forced out, not elevated.", "tag": "reversed"}, {"text": "commendation", "why": "Reversed: commendation means formal praise, the opposite of the punitive removal the staff protested.", "tag": "reversed"}, {"text": "resignation", "why": "Too specific: resignation is a voluntary departure, but the passage says the editor was forced out by others, not that she chose to leave.", "tag": "too-specific"}, {"text": "dismissal", "why": "The clues 'without any stated reason' and 'force her out' point to a removal or discharge from her position, which is what dismissal means."}], "answer": 3},
{"id": "vq-mh-disparage", "wordId": "mh-disparage", "skill": "words-in-context", "stem": "Early reviewers were quick to ______ Emily Dickinson's unconventional style, dismissing her dashes and slanted rhymes as the careless mistakes of an untrained amateur rather than recognizing them as bold and deliberate artistic choices.", "choices": [{"text": "celebrate", "why": "Reversed: celebrate means to praise or honor, the opposite of calling her work careless mistakes.", "tag": "reversed"}, {"text": "disparage", "why": "The clue 'the careless mistakes of an untrained amateur' shows the reviewers were belittling Dickinson's style, which is what disparage means."}, {"text": "critique", "why": "Too broad: critique means to evaluate, which can be neutral or fair, but the passage shows the reviewers were specifically running the work down.", "tag": "too-broad"}, {"text": "emulate", "why": "Unsupported: emulate means to imitate admiringly, but the reviewers scorned her work rather than copying it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-disparity", "wordId": "mh-disparity", "skill": "words-in-context", "stem": "A recent public-health study documented a striking ______ in life expectancy between two neighborhoods only a few miles apart: residents of the wealthier district lived, on average, a full decade longer than their neighbors in the poorer one.", "choices": [{"text": "parity", "why": "Reversed: parity means equality, but the study found a ten-year gap, not equal outcomes.", "tag": "reversed"}, {"text": "consensus", "why": "Unsupported: consensus means general agreement, which has nothing to do with a difference in life expectancy.", "tag": "unsupported"}, {"text": "variation", "why": "Too broad: variation means ordinary range of difference, but disparity better captures the stark, consequential ten-year gap the passage emphasizes.", "tag": "too-broad"}, {"text": "disparity", "why": "The clue 'a full decade longer' between two nearby neighborhoods signals a marked difference or gap, which is what disparity means."}], "answer": 3},
{"id": "vq-mh-disregard", "wordId": "mh-disregard", "skill": "words-in-context", "stem": "Confident in their own maps, the expedition's leaders chose to ______ the repeated warnings of local guides about the mountain's sudden afternoon storms, a decision that stranded the party above the tree line and nearly cost every member their life.", "choices": [{"text": "heed", "why": "Reversed: heed means to pay careful attention and act on advice, but the leaders ignored the guides and paid dearly.", "tag": "reversed"}, {"text": "exaggerate", "why": "Unsupported: exaggerate means to overstate, but the leaders took the warnings less seriously, not more.", "tag": "unsupported"}, {"text": "disregard", "why": "The clue 'confident in their own maps' plus the disastrous outcome shows the leaders ignored the guides' warnings, which is what disregard means."}, {"text": "downplay", "why": "Too specific: downplay means to make something seem less important, but the passage shows the leaders ignored the warnings entirely rather than merely minimizing them.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-dissipate", "wordId": "mh-dissipate", "skill": "words-in-context", "stem": "As the final encore faded, the electric tension that had gripped the packed arena began to ______; within minutes the once-frenzied crowd had settled into calm, unhurried streams filing quietly toward the exits.", "choices": [{"text": "intensify", "why": "Reversed: intensify means to grow stronger, but the tension was fading as the crowd grew calm.", "tag": "reversed"}, {"text": "linger", "why": "Reversed: linger means to persist and remain, the opposite of tension melting away within minutes.", "tag": "reversed"}, {"text": "resurface", "why": "Unsupported: resurface means to reappear after being hidden, but the tension was disappearing, not returning.", "tag": "unsupported"}, {"text": "dissipate", "why": "The clue 'within minutes the once-frenzied crowd had settled into calm' shows the tension scattered and faded away, which is what dissipate means."}], "answer": 3},
{"id": "vq-mh-dissociate", "wordId": "mh-dissociate", "skill": "words-in-context", "stem": "Alarmed that her findings were being cited to justify the sweeping policy, the biologist publicly moved to ______ herself from the campaign entirely, insisting that her data had been twisted beyond recognition and demanding that her name be removed from its literature.", "choices": [{"text": "dissociate", "why": "The clues 'insisting her data had been twisted' and 'demanding her name be removed' show she is severing her connection to the campaign, which is what dissociate means."}, {"text": "align", "why": "Reversed: align means to join with or take the side of, the opposite of the biologist distancing herself.", "tag": "reversed"}, {"text": "reconcile", "why": "Unsupported: reconcile means to restore friendly relations, but she is cutting ties, not repairing them.", "tag": "unsupported"}, {"text": "implicate", "why": "Reversed: implicate means to show involvement in, connecting her to the campaign rather than separating her from it.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-dissolve", "wordId": "mh-dissolve", "skill": "words-in-context", "stem": "Over thousands of years, mildly acidic rainwater seeps into the ground and can chemically ______ solid limestone, breaking the rock apart at the molecular level and washing the minerals away to hollow out the vast chambers and winding passages of a cave system.", "choices": [{"text": "fortify", "why": "Reversed: fortify means to strengthen or reinforce, but the rainwater is breaking the rock down, not building it up.", "tag": "reversed"}, {"text": "erode", "why": "Too broad: erode means to wear away gradually by mechanical action, but the passage specifies a chemical breakdown 'at the molecular level,' which is dissolving.", "tag": "too-broad"}, {"text": "dissolve", "why": "The clue 'chemically... breaking the rock apart at the molecular level and washing the minerals away' describes matter breaking down into a liquid, which is what dissolve means."}, {"text": "petrify", "why": "Reversed: petrify means to harden into stone, the opposite of breaking the limestone down.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-entrust", "wordId": "mh-entrust", "skill": "words-in-context", "stem": "Because the archive's fifteenth-century manuscripts demand highly specialized handling, the university's librarians voted to ______ their conservation to a private laboratory whose staff has spent decades stabilizing fragile parchment.", "choices": [{"text": "attribute", "why": "To attribute is to credit something as a cause or source; the librarians are assigning a duty, not assigning credit for one.", "tag": "unsupported"}, {"text": "relegate", "why": "To relegate is to consign to an inferior position or rank; the passage presents the laboratory as a respected expert, not a lesser destination.", "tag": "reversed"}, {"text": "entrust", "why": "The manuscripts 'demand highly specialized handling' and the lab has 'decades' of expertise, so the librarians are confidently assigning the care to a trusted party — precisely what entrust means."}, {"text": "abandon", "why": "To abandon something to someone is to give it up carelessly or in defeat; the vote described is a deliberate, trusting delegation, not a careless surrender.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-epitome", "wordId": "mh-epitome", "skill": "words-in-context", "stem": "With its rigorously symmetrical façade, harmonious proportions, and temple-front portico, Palladio's Villa Rotonda is widely regarded as the ______ of Renaissance classicism: nearly every ideal the movement articulated finds full expression in the building.", "choices": [{"text": "antithesis", "why": "An antithesis is a direct opposite; the villa expresses the movement's ideals rather than contradicting them.", "tag": "reversed"}, {"text": "forerunner", "why": "A forerunner precedes and anticipates a movement; the villa embodies ideals the movement had already articulated, so it exemplifies rather than foreshadows them.", "tag": "unsupported"}, {"text": "vestige", "why": "A vestige is a surviving trace of something that has largely vanished; nothing in the passage suggests classicism had disappeared.", "tag": "unsupported"}, {"text": "epitome", "why": "The colon explains that 'nearly every ideal ... finds full expression in the building,' so the blank must mean the perfect example or embodiment."}], "answer": 3},
{"id": "vq-mh-evade", "wordId": "mh-evade", "skill": "words-in-context", "stem": "During the congressional hearing, the executive repeatedly sought to ______ questions about the firm's accounting practices, responding with vague generalities whenever senators pressed for specific figures.", "choices": [{"text": "evade", "why": "Answering with 'vague generalities' instead of the requested specifics is a way of avoiding the questions — the core meaning of evade."}, {"text": "rebut", "why": "To rebut is to argue directly against a claim with counterevidence; vague generalities are dodges, not counterarguments.", "tag": "unsupported"}, {"text": "clarify", "why": "To clarify is to make clearer; offering vague generalities is the opposite of clarification.", "tag": "reversed"}, {"text": "anticipate", "why": "To anticipate is to foresee or prepare for in advance; the passage describes his behavior during questioning, not any advance preparation.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-evasion", "wordId": "mh-evasion", "skill": "words-in-context", "stem": "Tiger moths respond to a bat's sonar with sudden dives and erratic spirals, a strategy of ______ that lets the insects slip free of pursuit rather than confront their predators directly.", "choices": [{"text": "retaliation", "why": "Retaliation means striking back; the moths flee, and the passage explicitly rules out confronting the predator.", "tag": "reversed"}, {"text": "evasion", "why": "The appositive defines the strategy as one that lets the moths 'slip free of pursuit,' which is exactly what evasion — escape or avoidance — means."}, {"text": "camouflage", "why": "Camouflage is concealment by blending into surroundings; dives and spirals are conspicuous escape maneuvers, not disguise.", "tag": "unsupported"}, {"text": "migration", "why": "Migration is seasonal, long-distance relocation; a split-second dodge of a hunting bat is out of that word's scope entirely.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-exceed", "wordId": "mh-exceed", "skill": "words-in-context", "stem": "Engineers report that the laboratory's new perovskite solar cells ______ the efficiency of conventional silicon panels by a wide margin, converting nearly ten percent more of the available sunlight into usable electricity.", "choices": [{"text": "match", "why": "Match means to equal; 'by a wide margin' and 'ten percent more' describe surpassing, not parity.", "tag": "unsupported"}, {"text": "exceed", "why": "'By a wide margin' and 'ten percent more' show the new cells go beyond the old panels' efficiency — the meaning of exceed."}, {"text": "approach", "why": "Approach means to come near to a level while still falling short; the cells have already surpassed the panels, not merely closed the gap.", "tag": "reversed"}, {"text": "trail", "why": "Trail means to lag behind; converting ten percent more sunlight puts the new cells ahead, not behind.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-exemplar", "wordId": "mh-exemplar", "skill": "words-in-context", "stem": "Scholars of medieval art routinely treat the Book of Kells as the finest ______ of insular illumination, a model whose intricate initials and interlace set the standard against which other manuscripts are judged.", "choices": [{"text": "anomaly", "why": "An anomaly deviates from the norm; the manuscript defines the norm, since others are judged against it.", "tag": "reversed"}, {"text": "imitation", "why": "An imitation is a copy of something else; the appositive calls the book 'a model ... [that] set the standard' — the thing copied, not the copy.", "tag": "reversed"}, {"text": "fragment", "why": "A fragment is a broken-off or incomplete piece; nothing in the passage suggests the manuscript is partial or damaged.", "tag": "unsupported"}, {"text": "exemplar", "why": "The appositive 'a model ... set the standard against which other manuscripts are judged' defines an ideal example — precisely what exemplar means."}], "answer": 3},
{"id": "vq-mh-exorbitant", "wordId": "mh-exorbitant", "skill": "words-in-context", "stem": "Letters from the California gold fields complain that merchants in remote mining camps charged ______ prices for basic supplies: a barrel of flour costing six dollars in San Francisco might sell for ten times that sum upriver.", "choices": [{"text": "negligible", "why": "Negligible means too small to matter; a tenfold markup is anything but trivial.", "tag": "reversed"}, {"text": "competitive", "why": "Competitive prices are in line with or below the going market rate; ten times the San Francisco price is far above it.", "tag": "reversed"}, {"text": "exorbitant", "why": "The colon's example — flour selling for 'ten times' its city price — plus the miners' complaints show the prices were unreasonably excessive, the meaning of exorbitant."}, {"text": "arbitrary", "why": "Arbitrary means set by whim without reason; the passage's clue quantifies how excessively high the prices were, not how randomly they were chosen.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-expediency", "wordId": "mh-expediency", "skill": "words-in-context", "stem": "Critics of the 1878 treaty argued that its terms reflected not principle but ______: the diplomats accepted whatever boundary lines could be ratified quickly, deferring every question of justice to later conferences.", "choices": [{"text": "idealism", "why": "Idealism is commitment to principle over practicality — the very motive the sentence denies with 'not principle but.'", "tag": "reversed"}, {"text": "transparency", "why": "Transparency means openness about one's dealings; the passage concerns the diplomats' motives, and secrecy is never at issue.", "tag": "unsupported"}, {"text": "deliberation", "why": "Deliberation is slow, careful weighing of options; accepting 'whatever ... could be ratified quickly' rules out unhurried consideration.", "tag": "reversed"}, {"text": "expediency", "why": "The contrast 'not principle but' plus accepting 'whatever ... could be ratified quickly' while deferring justice defines choosing convenience over principle — the meaning of expediency."}], "answer": 3},
{"id": "vq-mh-embrace", "wordId": "mh-embrace", "skill": "words-in-context", "stem": "When a struggling museum finally recognized that its aging exhibits deterred younger visitors, its board voted to ______ digital installations that critics had once dismissed as gimmicks—a decision that ultimately reversed years of declining attendance.", "choices": [{"text": "embrace", "why": "The board reversed declining attendance by actively taking up installations it once dismissed, so the blank must mean to accept and adopt—embrace."}, {"text": "spurn", "why": "Spurn means to reject with contempt, the opposite of the board's decision to welcome the new installations.", "tag": "reversed"}, {"text": "tolerate", "why": "Tolerate means merely to put up with; the board did more than passively allow the installations—it committed to them.", "tag": "too-broad"}, {"text": "scrutinize", "why": "Scrutinize means to examine closely; nothing in the passage concerns inspecting the installations, only deciding to adopt them.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-emend", "wordId": "mh-emend", "skill": "words-in-context", "stem": "Comparing several surviving copies of the medieval chronicle, the scholar found that a single scribal slip had been propagated for centuries; only by consulting the earliest manuscript could she ______ the passage and restore the author's original wording.", "choices": [{"text": "transcribe", "why": "Transcribe means to copy out text; that is precisely what the earlier scribes did wrong—the scholar needed to correct, not merely copy.", "tag": "unsupported"}, {"text": "emend", "why": "The scholar aims to remove a propagated error and restore the original wording, so the blank must mean to correct a text—emend."}, {"text": "fabricate", "why": "Fabricate means to invent or falsify, the opposite of restoring an author's true original wording.", "tag": "reversed"}, {"text": "censor", "why": "Censor means to suppress objectionable content; the passage concerns fixing an error, not removing offensive material.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-emissaries", "wordId": "mh-emissaries", "skill": "words-in-context", "stem": "Unable to cross the treacherous mountain passes himself, the aging monarch dispatched trusted ______ to the rival court, empowering them to negotiate a treaty and speak on his behalf.", "choices": [{"text": "mercenaries", "why": "Mercenaries are soldiers who fight for pay; the monarch's agents were sent to negotiate, not to wage war.", "tag": "unsupported"}, {"text": "dissidents", "why": "Dissidents oppose the ruling authority, whereas these agents act on the monarch's behalf, not against him.", "tag": "unsupported"}, {"text": "emissaries", "why": "They are dispatched to the rival court, empowered to negotiate and to speak on the monarch's behalf—the defining role of emissaries."}, {"text": "chroniclers", "why": "Chroniclers record events in writing; nothing suggests the agents were historians rather than negotiators.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-encapsulate", "wordId": "mh-encapsulate", "skill": "words-in-context", "stem": "The critic praised the novel's final paragraph for its economy: in two spare sentences it seemed to ______ the entire family's decades of quiet disappointment, distilling a sprawling saga into a single, resonant image.", "choices": [{"text": "embellish", "why": "Embellish means to add decorative detail, the opposite of the economy and distillation the passage praises.", "tag": "reversed"}, {"text": "catalog", "why": "To catalog is to list items one by one; the paragraph condenses a saga into a single image rather than enumerating it.", "tag": "unsupported"}, {"text": "protract", "why": "Protract means to draw out or lengthen, contradicting the praised brevity of 'two spare sentences.'", "tag": "reversed"}, {"text": "encapsulate", "why": "'Distilling a sprawling saga into a single, resonant image' signals compressing an entire meaning into a tiny space—to encapsulate."}], "answer": 3},
{"id": "vq-mh-endure", "wordId": "mh-endure", "skill": "words-in-context", "stem": "Archaeologists marvel that the Roman aqueduct, assembled without mortar from precisely cut stone, could ______ two thousand years of earthquakes and floods while far newer structures nearby have already crumbled into rubble.", "choices": [{"text": "endure", "why": "The aqueduct lasted through two millennia of earthquakes and floods while newer structures crumbled, so the blank means to withstand and survive—endure."}, {"text": "collapse", "why": "Collapse means to fall apart, exactly what the surviving aqueduct did not do.", "tag": "reversed"}, {"text": "predate", "why": "Predate means to come before in time; the point is survival through the centuries, not chronological precedence.", "tag": "unsupported"}, {"text": "succumb", "why": "Succumb means to give way or yield, the opposite of surviving harsh forces intact.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-engender", "wordId": "mh-engender", "skill": "words-in-context", "stem": "Economists warn that abruptly slashing food subsidies, however sound in theory, tends to ______ widespread unrest, as families who suddenly cannot afford staples take their grievances into the streets.", "choices": [{"text": "quell", "why": "Quell means to put down or suppress; slashing subsidies produces unrest rather than quieting it.", "tag": "reversed"}, {"text": "forecast", "why": "Forecast means to predict; the passage says the policy causes unrest, not that it merely anticipates it.", "tag": "unsupported"}, {"text": "engender", "why": "Families who cannot afford staples take grievances to the streets, so cutting subsidies gives rise to unrest—engender."}, {"text": "alleviate", "why": "Alleviate means to ease; the policy worsens hardship and provokes unrest, the opposite of relieving it.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-engendering", "wordId": "mh-engendering", "skill": "words-in-context", "stem": "The rapid spread of generative image tools is ______ fresh anxieties among photographers, who fear that a flood of synthetic pictures will make it impossible for audiences to trust that any photograph depicts a real event.", "choices": [{"text": "dispelling", "why": "Dispelling means driving away; the tools create new anxieties rather than removing them.", "tag": "reversed"}, {"text": "documenting", "why": "Documenting means recording; the tools generate the fears, not merely note them down.", "tag": "unsupported"}, {"text": "mirroring", "why": "Mirroring means reflecting something that already exists, but the passage says the fears are freshly produced.", "tag": "unsupported"}, {"text": "engendering", "why": "Photographers' fear of a flood of synthetic images is an anxiety newly produced by the tools' spread, so the blank means causing—engendering."}], "answer": 3},
{"id": "vq-mh-enlist", "wordId": "mh-enlist", "skill": "words-in-context", "stem": "To map bird populations across an entire continent, ornithologists could never gather enough data alone, so they ______ thousands of amateur birdwatchers, training these volunteers to record every sighting through a shared smartphone app.", "choices": [{"text": "dismiss", "why": "Dismiss means to send away, the opposite of bringing thousands of volunteers on board.", "tag": "reversed"}, {"text": "enlist", "why": "Needing more hands, the ornithologists recruit thousands of amateur birdwatchers and train them to help, so the blank means to enroll helpers—enlist."}, {"text": "supervise", "why": "Supervise means to oversee people already working; it presupposes the recruiting the sentence is actually describing.", "tag": "unsupported"}, {"text": "impersonate", "why": "Impersonate means to pretend to be someone else and has no bearing on gathering volunteers.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-entail", "wordId": "mh-entail", "skill": "words-in-context", "stem": "Peer review is far more demanding than outsiders assume: evaluating a single submission may ______ weeks of checking equations, rerunning analyses, and combing the literature for overlooked studies, all done without pay.", "choices": [{"text": "preclude", "why": "Preclude means to prevent or rule out; the passage says review demands this work, not that it prevents it.", "tag": "reversed"}, {"text": "forgo", "why": "Forgo means to do without; reviewers perform the weeks of checking rather than skipping it.", "tag": "unsupported"}, {"text": "entail", "why": "Reviewing a submission may involve weeks of checking equations, rerunning analyses, and searching the literature, so the blank means to require or involve—entail."}, {"text": "expedite", "why": "Expedite means to speed up, contradicting the picture of a slow, weeks-long, demanding process.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-expedite", "wordId": "mh-expedite", "skill": "words-in-context", "stem": "Frustrated by the mountains of paperwork that delayed each shipment for weeks, the port authority introduced a new digital manifest system meant to ______ the clearance of relief cargo, so that emergency aid could reach disaster zones in a matter of days rather than weeks.", "choices": [{"text": "expedite", "why": "The days-versus-weeks contrast signals the system is meant to speed the process up, which is exactly what to expedite means."}, {"text": "facilitate", "why": "To make easier, but not specifically to make faster; the passage's whole point is acceleration, so this near-synonym misses the precise dimension.", "tag": "too-broad"}, {"text": "protract", "why": "Means to prolong or draw out, the opposite of the intended speeding up.", "tag": "reversed"}, {"text": "allocate", "why": "Means to distribute or assign resources, a budgeting notion unrelated to the timing of clearance.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-explicable", "wordId": "mh-explicable", "skill": "words-in-context", "stem": "To later historians, the sudden collapse of the once-prosperous trading city seemed baffling; only after archaeologists uncovered evidence of a prolonged drought and repeated failed harvests did the decline become fully ______, its causes traceable to a chain of environmental crises.", "choices": [{"text": "explicable", "why": "Once the drought evidence made the causes 'traceable,' the once-baffling collapse became able to be accounted for, the meaning of explicable."}, {"text": "inexplicable", "why": "Means impossible to explain, but the passage says the discovery finally made the decline understandable.", "tag": "reversed"}, {"text": "justifiable", "why": "Means able to be shown as right or reasonable, a moral judgment; the passage is about understanding causes, not defending the collapse.", "tag": "unsupported"}, {"text": "negligible", "why": "Means too small to matter, which has nothing to do with whether the decline can be accounted for.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-exploit", "wordId": "mh-exploit", "skill": "words-in-context", "stem": "Certain desert plants have evolved shallow, wide-spreading root systems that allow them to ______ the brief seasonal rains as fully as possible, absorbing enormous quantities of water in the few hours before the parched soil dries out completely again.", "choices": [{"text": "squander", "why": "Means to waste, the opposite of making the fullest possible use of the scarce rain.", "tag": "reversed"}, {"text": "exploit", "why": "'As fully as possible' and 'absorbing enormous quantities' show the plants make maximal advantageous use of the rains, the sense of exploit."}, {"text": "exhaust", "why": "Means to use up or deplete a source entirely, focusing on emptying it rather than turning a fleeting opportunity to advantage.", "tag": "too-specific"}, {"text": "replenish", "why": "Means to refill or restore; the plants take up the water, they do not restore it.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-extort", "wordId": "mh-extort", "skill": "words-in-context", "stem": "In the corrupt port city depicted in the novel, harbor officials routinely threatened to impound vessels on invented technicalities, a scheme designed to ______ hefty bribes from captains who could not afford the ruinous delays of a seized ship.", "choices": [{"text": "extort", "why": "Obtaining payment through threats of impoundment is precisely to extort, which means to force money by coercion."}, {"text": "solicit", "why": "Means simply to request or seek, omitting the element of threat and coercion the passage emphasizes.", "tag": "too-broad"}, {"text": "embezzle", "why": "Means to steal funds entrusted to one's care, but the officials are forcing outside payments through intimidation, not misappropriating held money.", "tag": "unsupported"}, {"text": "decline", "why": "Means to refuse, the opposite direction of officials coercing payments for themselves.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-extrapolate", "wordId": "mh-extrapolate", "skill": "words-in-context", "stem": "Because direct measurements of ocean temperatures before 1900 simply do not exist, paleoclimatologists must ______ earlier conditions from indirect evidence such as coral growth rings and sediment layers, projecting the patterns preserved in these records back across the centuries.", "choices": [{"text": "observe", "why": "Means to perceive directly, which is impossible here since the passage says no direct measurements exist.", "tag": "reversed"}, {"text": "fabricate", "why": "Means to invent falsely, but the scientists infer from real physical evidence rather than making data up.", "tag": "unsupported"}, {"text": "extrapolate", "why": "'Projecting the patterns...back across the centuries' from existing records is exactly to extrapolate, to infer beyond the observed range."}, {"text": "estimate", "why": "Means to approximate a value, but the passage stresses projecting known patterns beyond the measured range, the specific work of extrapolation.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-mh-facetious", "wordId": "mh-facetious", "skill": "words-in-context", "stem": "The critic complained that whenever the playwright approached a genuinely tragic moment, he undercut it with a ______ aside, some flippant quip that drew easy laughs but left audiences unable to take the characters' suffering seriously.", "choices": [{"text": "solemn", "why": "Means grave and serious, the opposite of the light, laugh-drawing quip described.", "tag": "reversed"}, {"text": "earnest", "why": "Means sincere and heartfelt, contradicting the flippant, joking tone the passage attributes to the aside.", "tag": "reversed"}, {"text": "sardonic", "why": "Means bitterly mocking or scornful, but the aside 'drew easy laughs' and is playful rather than derisive.", "tag": "too-specific"}, {"text": "facetious", "why": "A 'flippant quip that drew easy laughs' at a serious moment is facetious, meaning jokey, especially inappropriately so."}], "answer": 3},
{"id": "vq-mh-feasible", "wordId": "mh-feasible", "skill": "words-in-context", "stem": "Early proposals to build an elevator into space were dismissed as fantasy, but as ultralight carbon materials grow stronger and cheaper, some engineers now argue the concept may at last be ______, not certain to succeed, but at least practical enough to justify a serious attempt.", "choices": [{"text": "feasible", "why": "'Practical enough to justify a serious attempt' matches feasible, meaning capable of being done."}, {"text": "inconceivable", "why": "Means impossible even to imagine, the opposite of a concept engineers now think can be attempted.", "tag": "reversed"}, {"text": "inevitable", "why": "Means certain to happen, but the passage explicitly says the project is 'not certain to succeed.'", "tag": "too-specific"}, {"text": "profitable", "why": "Concerns financial gain, but the point is whether the project can be built, not whether it will earn money.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-fecundity", "wordId": "mh-fecundity", "skill": "words-in-context", "stem": "Critics marveled at the ______ of the novelist's imagination: in barely fifteen years she produced more than forty novels, dozens of short stories, and several plays, each teeming with vivid characters and intricate, tightly woven plots.", "choices": [{"text": "sterility", "why": "Means barrenness or inability to produce, the opposite of the abundant output the colon documents.", "tag": "reversed"}, {"text": "fecundity", "why": "Forty novels and dozens of stories in fifteen years illustrate the fruitful, prolific productivity that fecundity names."}, {"text": "austerity", "why": "Means severe plainness or restraint, contradicting the overflowing, teeming abundance described.", "tag": "reversed"}, {"text": "ingenuity", "why": "Means inventive cleverness, but the passage stresses sheer prolific abundance of output, not merely how clever the work is.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-foment", "wordId": "mh-foment", "skill": "words-in-context", "stem": "Colonial authorities regarded the pamphleteer as dangerous not because he took up arms himself, but because his fiery essays seemed calculated to ______ rebellion among the tenant farmers, stirring resentment that might at any moment erupt into open revolt.", "choices": [{"text": "quell", "why": "Means to suppress or put down, the opposite of essays designed to stir up revolt.", "tag": "reversed"}, {"text": "avert", "why": "Means to prevent, contradicting the passage's picture of essays meant to provoke rebellion.", "tag": "reversed"}, {"text": "foment", "why": "'Calculated to...stir resentment' into 'open revolt' captures foment, meaning to provoke or stir up trouble."}, {"text": "anticipate", "why": "Means to foresee or expect, but the essays actively incite the rebellion rather than merely predict it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-fortitude", "wordId": "mh-fortitude", "skill": "words-in-context", "stem": "Ernest Shackleton's crew, stranded on the Antarctic ice for months, survived on the sheer ______ of their captain, who endured freezing conditions and dwindling supplies without ever betraying despair to the men who depended on him.", "choices": [{"text": "fortitude", "why": "'Endured freezing conditions ... without ever betraying despair' names the steady strength to withstand hardship that fortitude denotes.", "tag": ""}, {"text": "audacity", "why": "Unsupported: audacity means bold daring or recklessness, whereas the captain shows patient endurance, not risk-taking.", "tag": "unsupported"}, {"text": "vitality", "why": "Too specific: vitality means physical energy or liveliness, not the moral strength to endure suffering the passage emphasizes.", "tag": "too-specific"}, {"text": "complacency", "why": "Reversed: complacency is smug self-satisfaction, the opposite of the resolve needed to struggle against extreme adversity.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-grudgingly", "wordId": "mh-grudgingly", "skill": "words-in-context", "stem": "Having insisted for months that his rival's economic plan would fail, the senator finally and ______ conceded its success, admitting the results only because the mounting evidence left him no honorable way to deny them.", "choices": [{"text": "graciously", "why": "Reversed: graciously means with warm generosity, the opposite of the resentful, forced concession described.", "tag": "reversed"}, {"text": "eagerly", "why": "Reversed: eagerly means enthusiastically, but the senator resisted the admission until the evidence forced it.", "tag": "reversed"}, {"text": "candidly", "why": "Unsupported: candidly means frankly and openly; nothing shows frankness, only a concession dragged out of him.", "tag": "unsupported"}, {"text": "grudgingly", "why": "'Insisted for months it would fail' and 'admitting only because ... no way to deny' establish reluctant, unwilling agreement, which is grudgingly.", "tag": ""}], "answer": 3},
{"id": "vq-mh-habitable", "wordId": "mh-habitable", "skill": "words-in-context", "stem": "After the flood, engineers spent two years reinforcing the foundations and replacing the ruined wiring until the old tenement was once again ______: families could finally move back into apartments that had stood empty and unsafe for a decade.", "choices": [{"text": "habitable", "why": "'Families could finally move back into apartments' shows the building was fit to live in, the meaning of habitable.", "tag": ""}, {"text": "arable", "why": "Wrong domain: arable means suitable for growing crops, not fit for people to live in.", "tag": "unsupported"}, {"text": "temperate", "why": "Unsupported: temperate means mild in climate; the passage concerns structural safety, not weather.", "tag": "unsupported"}, {"text": "spacious", "why": "True but irrelevant: spacious means roomy, but size is not what the repairs restored or what made the building fit to occupy.", "tag": "true-but-irrelevant"}], "answer": 0},
{"id": "vq-mh-hallmark", "wordId": "mh-hallmark", "skill": "words-in-context", "stem": "Sudden shifts between whispered passages and thunderous crescendos became the ______ of the composer's style: critics could identify her work within seconds precisely because that dramatic contrast appeared in nearly every piece she wrote.", "choices": [{"text": "anomaly", "why": "Reversed: an anomaly is a rare deviation, but the trait appears in nearly every piece, making it typical rather than exceptional.", "tag": "reversed"}, {"text": "byproduct", "why": "Unsupported: a byproduct is an incidental side effect, not the defining, instantly recognizable feature described.", "tag": "unsupported"}, {"text": "hallmark", "why": "'Critics could identify her work ... because that contrast appeared in nearly every piece' names a defining characteristic, which is a hallmark.", "tag": ""}, {"text": "novelty", "why": "Unsupported: a novelty is something new or unusual, but this feature is consistent and characteristic, not a one-off curiosity.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-hamper", "wordId": "mh-hamper", "skill": "words-in-context", "stem": "The researchers warned that a shortage of trained technicians would severely ______ the vaccine trial, slowing the collection of data and threatening to push the final results back by many months.", "choices": [{"text": "expedite", "why": "Reversed: to expedite is to speed up, the opposite of slowing the trial and delaying its results.", "tag": "reversed"}, {"text": "hamper", "why": "'Slowing the collection of data and threatening to push the results back' describes obstructing progress, the meaning of hamper.", "tag": ""}, {"text": "streamline", "why": "Reversed: to streamline is to make more efficient, but a staffing shortage obstructs rather than improves the work.", "tag": "reversed"}, {"text": "supplement", "why": "Out of scope: to supplement is to add to something; a shortage does not add resources, it impedes the trial.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-harbinger", "wordId": "mh-harbinger", "skill": "words-in-context", "stem": "In many folk traditions the sudden appearance of migrating storks was read as a ______ of spring, a first signal that the long, bitter winter was about to give way to warmer and greener days.", "choices": [{"text": "harbinger", "why": "'A first signal that ... winter was about to give way' names something that foreshadows what is coming, the meaning of harbinger.", "tag": ""}, {"text": "remnant", "why": "Reversed timing: a remnant is a leftover trace of something past, not a sign of what is about to arrive.", "tag": "reversed"}, {"text": "culmination", "why": "Reversed: a culmination is a high point or final result, not an early signal of a season still to come.", "tag": "reversed"}, {"text": "symptom", "why": "Too specific: a symptom indicates a present condition, usually illness, rather than foreshadowing a future change of season.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-mh-heterogeneous", "wordId": "mh-heterogeneous", "skill": "words-in-context", "stem": "When the geologists examined the boulder under a microscope, they found it was strikingly ______: fragments of at least five different rock types, each formed under distinct conditions, had been fused together into a single mass.", "choices": [{"text": "homogeneous", "why": "Reversed: homogeneous means uniform throughout and made of the same material, the opposite of five different rock types fused together.", "tag": "reversed"}, {"text": "heterogeneous", "why": "'Fragments of at least five different rock types ... fused together' describes something composed of diverse, dissimilar parts, which is heterogeneous.", "tag": ""}, {"text": "eclectic", "why": "Wrong domain: eclectic describes styles or collections deliberately drawn from many sources by taste, not the physical mixing of rock types.", "tag": "unsupported"}, {"text": "porous", "why": "Unsupported: porous means full of tiny holes, a different physical property than variety of composition.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-hideous", "wordId": "mh-hideous", "skill": "words-in-context", "stem": "The cathedral's gargoyles were carved to be deliberately ______: their bulging eyes, twisted snarls, and clawed limbs were meant to horrify passing onlookers and, according to legend, to frighten evil spirits away from the church.", "choices": [{"text": "ornate", "why": "Unsupported: ornate means elaborately decorated; the gargoyles are meant to horrify, not merely to look fancy.", "tag": "unsupported"}, {"text": "unsightly", "why": "Too weak: unsightly means mildly unattractive, far short of the horror the bulging eyes and snarls are meant to provoke.", "tag": "too-broad"}, {"text": "colossal", "why": "Out of scope: colossal means enormous in size, but the passage stresses ugliness and menace, not scale.", "tag": "unsupported"}, {"text": "hideous", "why": "'Bulging eyes, twisted snarls, and clawed limbs ... meant to horrify' describes something repulsively ugly, the meaning of hideous.", "tag": ""}], "answer": 3},
{"id": "vq-mh-homogeneous", "wordId": "mh-homogeneous", "skill": "words-in-context", "stem": "When the chemist stirred the solution thoroughly, the once-cloudy blend became perfectly ______: every drop drawn from the beaker now had precisely the same concentration and composition as every other.", "choices": [{"text": "volatile", "why": "Volatile means readily evaporating or unstable; the passage stresses uniformity of composition, not instability.", "tag": "unsupported"}, {"text": "saturated", "why": "Saturated describes a solution holding its maximum dissolved solute; it is a plausible chemistry term but refers to concentration limits, not sameness throughout.", "tag": "too-specific"}, {"text": "homogeneous", "why": "The elaboration that 'every drop had precisely the same concentration and composition' directly signals uniformity of parts throughout the mixture."}, {"text": "turbid", "why": "Turbid means cloudy or murky, the opposite of the clarified, uniform state the mixture reaches after stirring.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-idiosyncratic", "wordId": "mh-idiosyncratic", "skill": "words-in-context", "stem": "Critics can identify a Thelonious Monk recording within seconds because his playing is so ______: the angular phrasing, unexpected silences, and dissonant chords belong to no one else and mark every performance as unmistakably his own.", "choices": [{"text": "idiosyncratic", "why": "The clause 'belong to no one else... unmistakably his own' signals a style that is peculiar and distinctive to a single individual."}, {"text": "derivative", "why": "Derivative means imitative of others' work, the opposite of the wholly personal signature the passage celebrates.", "tag": "reversed"}, {"text": "conventional", "why": "Conventional means ordinary and conforming to accepted norms, which reverses the passage's point that his playing is uniquely recognizable.", "tag": "reversed"}, {"text": "erratic", "why": "Erratic means inconsistent and unpredictable; it tempts as 'unusual' but the passage stresses a consistent, recognizable signature across every performance, not inconsistency.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-idle", "wordId": "mh-idle", "skill": "words-in-context", "stem": "After the shipping company lost its largest contract, the massive cranes at the dock stood ______ for months, their engines cold and their operators sent home, while not a single container passed beneath them.", "choices": [{"text": "obsolete", "why": "Obsolete means outdated or no longer useful; the cranes are simply unused, not technologically superseded.", "tag": "unsupported"}, {"text": "idle", "why": "The details 'engines cold,' 'operators sent home,' and 'not a single container passed' establish that the cranes are inactive and out of use."}, {"text": "dilapidated", "why": "Dilapidated means fallen into disrepair, but the passage describes machinery that is unused rather than decaying.", "tag": "unsupported"}, {"text": "stagnant", "why": "Stagnant means failing to move or flow and is tied to standing water or a sluggish economy; it is the wrong domain for describing unused machinery.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-illusory", "wordId": "mh-illusory", "skill": "words-in-context", "stem": "The gambler's conviction that he was 'due' for a win after a long losing streak was entirely ______: the roulette wheel has no memory, so each spin's odds stay fixed regardless of what came before, and his sense of an approaching payoff existed only in his own mind.", "choices": [{"text": "rational", "why": "Rational means grounded in sound reasoning, the opposite of a belief the passage exposes as mistaken.", "tag": "reversed"}, {"text": "tangible", "why": "Tangible means real and perceptible, which reverses the point that the payoff 'existed only in his own mind.'", "tag": "reversed"}, {"text": "illusory", "why": "The evidence that the wheel 'has no memory' and that the feeling 'existed only in his own mind' shows the belief was deceptive and unreal."}, {"text": "provisional", "why": "Provisional means temporary or subject to revision; it is near in flavor but says nothing about the belief being false or deceptive.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-immutable", "wordId": "mh-immutable", "skill": "words-in-context", "stem": "Ancient astronomers regarded the patterns of the fixed stars as ______, believing that these constellations had held exactly the same shapes since the beginning of time and would never change for as long as the heavens endured.", "choices": [{"text": "arbitrary", "why": "Arbitrary means based on random choice; the passage stresses permanence and constancy, not randomness.", "tag": "unsupported"}, {"text": "transient", "why": "Transient means fleeting or short-lived, the opposite of shapes that persist unchanged since the beginning of time.", "tag": "reversed"}, {"text": "malleable", "why": "Malleable means easily shaped or altered, which reverses the passage's claim that the constellations would never change.", "tag": "reversed"}, {"text": "immutable", "why": "The clauses 'same shapes since the beginning of time' and 'would never change' directly express something unchangeable and fixed."}], "answer": 3},
{"id": "vq-mh-impart", "wordId": "mh-impart", "skill": "words-in-context", "stem": "The veteran surgeon hoped to ______ not just technical skill but hard-won judgment to her residents, passing along through years of shared operations the kind of practical wisdom that no textbook could ever contain.", "choices": [{"text": "impart", "why": "'Passing along... practical wisdom to her residents' matches conveying or communicating knowledge to others."}, {"text": "withhold", "why": "Withhold means to hold back or refuse to give, the opposite of the surgeon's aim to pass knowledge along.", "tag": "reversed"}, {"text": "extract", "why": "Extract means to draw out or remove from; it points in the wrong direction, taking knowledge rather than giving it.", "tag": "reversed"}, {"text": "embellish", "why": "Embellish means to decorate or exaggerate; nothing in the passage concerns adorning or dressing up the wisdom.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-impartiality", "wordId": "mh-impartiality", "skill": "words-in-context", "stem": "A respected news organization prizes ______ above all: its reporters are expected to present every side of a controversy with equal care, allowing no personal allegiance or political preference to color the facts they deliver to readers.", "choices": [{"text": "brevity", "why": "Brevity means conciseness; the passage concerns even-handed treatment of all sides, not the length of the reporting.", "tag": "unsupported"}, {"text": "impartiality", "why": "The elaboration that reporters treat 'every side with equal care' and let 'no personal allegiance' color the facts defines fairness and neutrality."}, {"text": "partisanship", "why": "Partisanship means biased support for one side, the exact opposite of the even-handedness the organization demands.", "tag": "reversed"}, {"text": "skepticism", "why": "Skepticism is a doubting, questioning attitude; it is a journalistic virtue that tempts but denotes questioning claims, not treating all sides evenhandedly.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-imperative", "wordId": "mh-imperative", "skill": "words-in-context", "stem": "Because contaminants can devastate the wetland's amphibian populations within weeks of entering the watershed, ecologists insist that continuous water-quality monitoring is ______; without it, a chemical spill could go undetected until the damage was irreversible.", "choices": [{"text": "imperative", "why": "The stakes named in the clues — devastation 'within weeks' and 'irreversible' damage without monitoring — make monitoring absolutely essential, which is exactly what imperative means."}, {"text": "beneficial", "why": "Too weak: beneficial means merely helpful, but the passage's logic ('without it... irreversible') presents monitoring as a necessity, not just an advantage.", "tag": "too-broad"}, {"text": "inconsequential", "why": "Reversed: inconsequential means unimportant, the opposite of what ecologists who 'insist' on monitoring to prevent irreversible damage would claim.", "tag": "reversed"}, {"text": "customary", "why": "Customary means done by habit or tradition; the passage argues from urgency and consequences, saying nothing about what is usual practice.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-implement", "wordId": "mh-implement", "skill": "words-in-context", "stem": "After a two-year pilot program in three neighborhoods reduced pedestrian injuries by nearly half, the city council voted unanimously to ______ the street redesign citywide, allocating funds to rebuild dangerous intersections over the next decade.", "choices": [{"text": "propose", "why": "The proposal stage is already past — the redesign has been piloted and approved; allocating funds to rebuild intersections means putting the plan into effect, not suggesting it.", "tag": "unsupported"}, {"text": "evaluate", "why": "True but irrelevant: evaluation already occurred through the two-year pilot; the vote and funding describe action taken after the assessment succeeded.", "tag": "true-but-irrelevant"}, {"text": "abandon", "why": "Reversed: the pilot's success and the decision to fund citywide rebuilding show the council embracing the redesign, not discarding it.", "tag": "reversed"}, {"text": "implement", "why": "The clues — a successful pilot, a unanimous vote, and funds allocated 'to rebuild dangerous intersections' — show the plan being carried out, so the blank must mean put into effect."}], "answer": 3},
{"id": "vq-mh-imposing", "wordId": "mh-imposing", "skill": "words-in-context", "stem": "Civic architects of the late nineteenth century intended courthouses to embody governmental authority: with its colossal granite columns and a facade towering over the surrounding shops, the Hamilton County courthouse strikes visitors as suitably ______.", "choices": [{"text": "inconspicuous", "why": "Reversed: inconspicuous means not easily noticed, but a building with colossal columns 'towering over the surrounding shops' is designed to be impossible to miss.", "tag": "reversed"}, {"text": "ornate", "why": "Too narrow: ornate refers to elaborate decorative detail, but the clues emphasize sheer scale and dominance — colossal columns, a towering facade — not ornamentation.", "tag": "too-specific"}, {"text": "functional", "why": "Functional means designed for practical use; the passage concerns the building's grand appearance and symbolic authority, not its utility.", "tag": "unsupported"}, {"text": "imposing", "why": "The colon links the blank to 'embody governmental authority,' and the clues — colossal columns, a facade towering over its surroundings — describe a grandly impressive presence, i.e., imposing."}], "answer": 3},
{"id": "vq-mh-improvised", "wordId": "mh-improvised", "skill": "words-in-context", "stem": "Newly recovered concert recordings confirm what the pianist's collaborators long claimed: many of her most celebrated passages were ______, invented at the keyboard in response to the room's acoustics rather than drawn from any written score.", "choices": [{"text": "rehearsed", "why": "Reversed: rehearsed means practiced in advance, but the passage says the passages were 'invented at the keyboard' in the moment, not prepared beforehand.", "tag": "reversed"}, {"text": "improvised", "why": "The appositive defines the blank — 'invented at the keyboard... rather than drawn from any written score' — which is precisely what improvised (created spontaneously, unplanned) means."}, {"text": "transcribed", "why": "Transcribed means written down from performance; the clue concerns how the music was created in the moment, not whether anyone later notated it.", "tag": "unsupported"}, {"text": "embellished", "why": "Too narrow: embellished means ornamenting pre-existing material, but the passage says the passages were invented outright, not decorated versions of a score.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-mh-impugn", "wordId": "mh-impugn", "skill": "words-in-context", "stem": "When a young geologist presented iridium evidence for an asteroid impact at the end of the Cretaceous period, rival researchers moved swiftly to ______ her methodology, alleging that her samples were contaminated and her dating techniques misapplied.", "choices": [{"text": "impugn", "why": "The participial clue — rivals 'alleging' contamination and misapplied techniques — describes attacking the work as untrustworthy, which is exactly what impugn (call into question, challenge as false) means."}, {"text": "corroborate", "why": "Reversed: corroborate means to confirm or support with evidence, the opposite of rivals alleging that the samples and techniques were faulty.", "tag": "reversed"}, {"text": "scrutinize", "why": "Too weak: scrutinize means only to examine closely and is neutral, but the allegations of contamination and misapplication signal a hostile attack on the work's validity.", "tag": "too-broad"}, {"text": "emulate", "why": "Emulate means to imitate in hopes of matching; nothing in the passage suggests the rivals wanted to copy her methods — they attacked them.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-inception", "wordId": "mh-inception", "skill": "words-in-context", "stem": "The Zurich observatory has recorded daily sunspot counts without interruption since the program's ______ in 1749, giving solar physicists the longest continuous data set in astronomy, one spanning more than twenty-five solar cycles.", "choices": [{"text": "culmination", "why": "Reversed: a culmination is a climactic endpoint, but a record that runs 'without interruption since... 1749' must be measured from the program's starting point.", "tag": "reversed"}, {"text": "debut", "why": "Wrong register: a debut is a first public performance or product launch; the founding moment of a long scientific program is its inception, not a debut.", "tag": "too-specific"}, {"text": "renovation", "why": "A renovation is a restoration of something already existing; the passage marks 1749 as the point the record began, not a later refurbishment.", "tag": "unsupported"}, {"text": "inception", "why": "An unbroken record kept 'since' 1749 and yielding 'the longest continuous data set' points to the program's beginning — its inception — as the anchor date."}], "answer": 3},
{"id": "vq-mh-incongruous", "wordId": "mh-incongruous", "skill": "words-in-context", "stem": "Residents of the historic district found the new forty-story tower ______: its mirrored glass facade and steel frame clashed jarringly with the preserved brick rowhouses that had defined the neighborhood's streetscape for two centuries.", "choices": [{"text": "harmonious", "why": "Reversed: harmonious means fitting agreeably together, the opposite of a facade that 'clashed jarringly' with its surroundings.", "tag": "reversed"}, {"text": "dilapidated", "why": "Dilapidated means fallen into disrepair; the tower is brand new, and the clue concerns stylistic mismatch, not physical decay.", "tag": "unsupported"}, {"text": "incongruous", "why": "The colon explains the judgment — glass and steel 'clashed jarringly' with two centuries of brick rowhouses — so the blank must mean out of keeping with its surroundings."}, {"text": "conspicuous", "why": "Too general: conspicuous says only that the tower is noticeable, missing the decisive clue that it clashed with — was mismatched to — its setting.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-mh-inconsequential", "wordId": "mh-inconsequential", "skill": "words-in-context", "stem": "Early reviewers dismissed the customs clerk's marginal notations as ______ — mere bookkeeping trivia with no bearing on larger events — yet historians later used those brief entries to reconstruct the entire Mediterranean trade network of the 1400s.", "choices": [{"text": "inconsequential", "why": "The appositive defines the blank — 'mere bookkeeping trivia with no bearing on larger events' — and the contrast with the notes' later historical value confirms the reviewers judged them unimportant."}, {"text": "invaluable", "why": "Reversed: invaluable means extremely useful, which describes what the notes proved to be later — the opposite of how the dismissive reviewers judged them.", "tag": "reversed"}, {"text": "incidental", "why": "Too narrow: incidental describes something arising as a chance byproduct, but the reviewers' verdict concerned the notes' importance, not how they came to exist.", "tag": "too-specific"}, {"text": "fraudulent", "why": "Fraudulent means deceitful or forged; the reviewers doubted the notes' significance, and nothing in the passage questions their authenticity.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-indices-of", "wordId": "mh-indices-of", "skill": "words-in-context", "stem": "Demographers treat declining birth rates and shrinking household sizes not as isolated curiosities but as reliable ______ broader social transformation: such measurable trends, they argue, reveal shifts in values that surveys alone cannot capture.", "choices": [{"text": "exceptions to", "why": "Exceptions to would make the trends anomalies that contradict social change, but the passage presents them as revealing that change.", "tag": "reversed"}, {"text": "obstacles to", "why": "Obstacles to implies the trends block transformation, whereas the text says they signal it.", "tag": "reversed"}, {"text": "indices of", "why": "The clue that these trends 'reveal shifts in values' shows the blank means indicators or signs of the larger transformation."}, {"text": "substitutes for", "why": "Substitutes for suggests the trends replace social change, but they are offered as evidence pointing to it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-indifferent", "wordId": "mh-indifferent", "skill": "words-in-context", "stem": "Although the newspaper published a scathing review of her debut novel, the author appeared entirely ______ to the assessment: she neither defended her work nor expressed any dismay, simply returning to her desk to begin the next chapter.", "choices": [{"text": "receptive", "why": "Receptive means openly welcoming a response, the opposite of the detachment shown by someone who neither reacted nor cared.", "tag": "reversed"}, {"text": "resigned", "why": "Resigned implies reluctant acceptance of something unwelcome, but the author registered no feeling at all about the review.", "tag": "too-specific"}, {"text": "bewildered", "why": "Bewildered means confused, yet nothing suggests she failed to understand the criticism; she simply had no reaction to it.", "tag": "unsupported"}, {"text": "indifferent", "why": "The detail that she 'neither defended her work nor expressed any dismay' establishes the blank as unconcerned or apathetic toward the review."}], "answer": 3},
{"id": "vq-mh-induce", "wordId": "mh-induce", "skill": "words-in-context", "stem": "Behavioral economists have shown that even small changes to a cafeteria's layout can ______ healthier choices: placing fruit at eye level, for instance, prompts many diners to select it without ever making a conscious decision to eat better.", "choices": [{"text": "suppress", "why": "Suppress means to hold back or stifle, the opposite of bringing about the healthier choices the layout encourages.", "tag": "reversed"}, {"text": "induce", "why": "The clue that eye-level fruit 'prompts many diners to select it' shows the blank means to cause or bring about those choices."}, {"text": "mandate", "why": "Mandate means to require by rule, but the passage describes a subtle nudge, not an enforced obligation.", "tag": "too-specific"}, {"text": "forecast", "why": "Forecast means to predict, whereas the layout actively produces the behavior rather than merely anticipating it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-inducement", "wordId": "mh-inducement", "skill": "words-in-context", "stem": "To attract settlers to the remote territory, the colonial government offered free acreage and a decade's exemption from taxes; these benefits served as the ______ that finally overcame most families' reluctance to relocate.", "choices": [{"text": "deterrent", "why": "A deterrent discourages action, the reverse of an offer designed to overcome reluctance and draw settlers in.", "tag": "reversed"}, {"text": "formality", "why": "A formality is a procedural nicety of little consequence, but the free land and tax relief are substantive motivators.", "tag": "unsupported"}, {"text": "inducement", "why": "The free acreage and tax exemption 'offered to attract settlers' identify the blank as an incentive or motivation to relocate."}, {"text": "grievance", "why": "A grievance is a complaint about a wrong, unrelated to the enticing benefits the government provided.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-ineluctable", "wordId": "mh-ineluctable", "skill": "words-in-context", "stem": "In classical tragedy, the hero's downfall is presented as ______: no matter how cleverly he maneuvers or how fervently he prays, the fate decreed at the outset closes in on him with the certainty of a mathematical proof.", "choices": [{"text": "avoidable", "why": "Avoidable means capable of being escaped, contradicting a fate that no maneuvering can prevent.", "tag": "reversed"}, {"text": "arbitrary", "why": "Arbitrary means random or without reason, but the downfall is described as decreed and certain, not capricious.", "tag": "unsupported"}, {"text": "gradual", "why": "Gradual describes slow pace, whereas the passage stresses the certainty of the outcome, not its speed.", "tag": "unsupported"}, {"text": "ineluctable", "why": "The image of fate closing in 'with the certainty of a mathematical proof' despite every effort shows the blank means unavoidable or inescapable."}], "answer": 3},
{"id": "vq-mh-inertia", "wordId": "mh-inertia", "skill": "words-in-context", "stem": "Despite mounting evidence that its flagship product was losing market share, the corporation was paralyzed by ______: entrenched routines and a reluctance to abandon familiar methods kept executives from making the reforms everyone privately acknowledged were overdue.", "choices": [{"text": "inertia", "why": "The 'entrenched routines and reluctance to abandon familiar methods' that block reform define the blank as inactivity and resistance to change."}, {"text": "volatility", "why": "Volatility means rapid, unpredictable change, the opposite of the stagnation keeping the firm from acting.", "tag": "reversed"}, {"text": "ambition", "why": "Ambition is a drive to achieve, contradicting a company that refuses to make overdue reforms.", "tag": "reversed"}, {"text": "attrition", "why": "Attrition means gradual reduction through losses, but the passage describes an unwillingness to act, not a wearing-down of resources.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-infer", "wordId": "mh-infer", "skill": "words-in-context", "stem": "Because soft tissue rarely survives fossilization, paleontologists must ______ an extinct animal's diet from indirect evidence: the shape of its teeth, the wear patterns along its jaw, and the chemical residues locked within its bones.", "choices": [{"text": "infer", "why": "Working 'from indirect evidence' such as teeth and wear patterns to reach a conclusion about diet is exactly to infer, or derive by reasoning."}, {"text": "dictate", "why": "Dictate means to command or impose, but scientists are reasoning toward a conclusion, not issuing one.", "tag": "unsupported"}, {"text": "observe", "why": "Observe implies direct perception, yet the passage stresses that the diet cannot be seen and must be reconstructed from clues.", "tag": "unsupported"}, {"text": "fabricate", "why": "Fabricate means to invent falsely, contradicting a process grounded in physical evidence.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-inferior", "wordId": "mh-inferior", "skill": "words-in-context", "stem": "Critics initially dismissed the mass-produced prints as ______ to the hand-painted originals, arguing that the mechanical process sacrificed the subtle gradations of color and texture that had given the originals their value.", "choices": [{"text": "superior", "why": "Superior means better, contradicting critics who dismissed the prints for lacking the originals' prized qualities.", "tag": "reversed"}, {"text": "inferior", "why": "The claim that the prints 'sacrificed the subtle gradations that gave the originals their value' marks the blank as lesser or substandard by comparison."}, {"text": "comparable", "why": "Comparable means roughly equal, but the critics judged the prints to fall short of the originals.", "tag": "reversed"}, {"text": "indispensable", "why": "Indispensable means essential, a claim unrelated to the critics' negative comparison of quality.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-infinitesimal", "wordId": "mh-infinitesimal", "skill": "words-in-context", "stem": "The new detector can register concentrations so ______ that they had eluded every earlier instrument: it responds to a single stray molecule dispersed among trillions, a quantity far too slight for older sensors to notice.", "choices": [{"text": "substantial", "why": "Substantial means large, the opposite of a quantity described as a single molecule among trillions.", "tag": "reversed"}, {"text": "volatile", "why": "Volatile means unstable or prone to change, which has no bearing on how small the concentration is.", "tag": "unsupported"}, {"text": "infinitesimal", "why": "The image of 'a single stray molecule among trillions, far too slight to notice' establishes the blank as vanishingly tiny or negligible."}, {"text": "pervasive", "why": "Pervasive means spread widely throughout, contradicting a concentration so minute it is nearly undetectable.", "tag": "reversed"}], "answer": 2},
{"id": "vq-mh-ingenious", "wordId": "mh-ingenious", "skill": "words-in-context", "stem": "Confronted by a chronic water shortage, the village engineer built an ______ arrangement of bamboo pipes and gravity-fed reservoirs — a design that solved in a single stroke a problem others had dismissed as hopeless, and that neighboring regions soon rushed to copy.", "choices": [{"text": "ingenious", "why": "The clue that the design 'solved in a single stroke a problem others had dismissed as hopeless' points to remarkable cleverness and inventiveness."}, {"text": "conventional", "why": "'Conventional' means ordinary or traditional, the reverse of a strikingly original solution that others had thought impossible.", "tag": "reversed"}, {"text": "elaborate", "why": "'Elaborate' means intricate or highly detailed; the passage praises the design's cleverness, not its complexity, and an elaborate design can still be clumsy.", "tag": "unsupported"}, {"text": "precarious", "why": "'Precarious' means unstable or risky; nothing in the passage suggests the system was fragile.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-insuperable", "wordId": "mh-insuperable", "skill": "words-in-context", "stem": "The earliest expeditions regarded the mountain's sheer ice walls as an ______ barrier; no climber, they were convinced, could ever devise a route past defenses so utterly absolute and unyielding.", "choices": [{"text": "negligible", "why": "'Negligible' means trivially small, the reverse of a barrier climbers thought no one could ever get past.", "tag": "reversed"}, {"text": "temporary", "why": "'Temporary' means short-lived; the climbers viewed the obstacle as permanently absolute, not passing.", "tag": "unsupported"}, {"text": "insuperable", "why": "That 'no climber could ever' pass 'defenses so utterly absolute' shows the barrier was considered impossible to overcome."}, {"text": "conspicuous", "why": "'Conspicuous' means easily noticed; visibility is not the quality the passage emphasizes about the barrier.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-insurmountable", "wordId": "mh-insurmountable", "skill": "words-in-context", "stem": "At the campaign's outset the funding gap looked ______, but an unexpected wave of small donations closed it within a few weeks, proving that the obstacle everyone had dreaded turned out to be entirely manageable.", "choices": [{"text": "trivial", "why": "'Trivial' means unimportant, the reverse of a gap that 'everyone had dreaded.'", "tag": "reversed"}, {"text": "artificial", "why": "'Artificial' means not genuine; the passage never suggests the funding gap was fabricated.", "tag": "unsupported"}, {"text": "predictable", "why": "'Predictable' means foreseeable; the point is the gap's apparent size, not whether it could be anticipated.", "tag": "unsupported"}, {"text": "insurmountable", "why": "The contrast marker 'but' against a gap that was later shown to be 'manageable' signals it had first seemed impossible to overcome."}], "answer": 3},
{"id": "vq-mh-intercede", "wordId": "mh-intercede", "skill": "words-in-context", "stem": "When negotiations between the two feuding guilds collapsed, the respected elder agreed to ______: she met privately with each side, carefully relayed their concerns, and gradually steered the rivals toward a workable compromise.", "choices": [{"text": "intercede", "why": "Meeting with 'each side' and steering them 'toward a compromise' describes intervening to mediate a dispute."}, {"text": "abstain", "why": "'Abstain' means to refrain from involvement, the reverse of the elder's active mediation.", "tag": "reversed"}, {"text": "adjudicate", "why": "'Adjudicate' means to judge formally and hand down a verdict; the elder guided both sides to agree rather than ruling over them.", "tag": "too-specific"}, {"text": "capitulate", "why": "'Capitulate' means to surrender; the elder was resolving the conflict, not giving in.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-interchangeable", "wordId": "mh-interchangeable", "skill": "words-in-context", "stem": "The engineer standardized every component so precisely that the parts became ______: a technician could pull a valve from one machine and drop it into another without any adjustment and without any loss of function.", "choices": [{"text": "obsolete", "why": "'Obsolete' means outdated; the passage describes parts that work perfectly across machines, not ones that are no longer usable.", "tag": "unsupported"}, {"text": "interchangeable", "why": "Parts a technician can move between machines 'without any adjustment' and 'without any loss of function' are substitutable for one another."}, {"text": "defective", "why": "'Defective' means faulty; the components clearly function correctly wherever they are placed.", "tag": "unsupported"}, {"text": "proprietary", "why": "'Proprietary' means exclusively owned and not freely shared or substituted, the opposite of parts that fit any machine.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-interconnected", "wordId": "mh-interconnected", "skill": "words-in-context", "stem": "Ecologists studying the coral reef discovered that its species were profoundly ______: the fortunes of the algae, the fish, and the invertebrates depended on one another so tightly that harm to any single group rippled outward through the whole system.", "choices": [{"text": "isolated", "why": "'Isolated' means separate and independent, the reverse of species whose fates 'depended on one another.'", "tag": "reversed"}, {"text": "abundant", "why": "'Abundant' means plentiful; the passage stresses mutual dependence, not sheer numbers.", "tag": "unsupported"}, {"text": "interconnected", "why": "Species that 'depended on one another so tightly' that harm to one 'rippled through the whole system' are linked together."}, {"text": "dormant", "why": "'Dormant' means inactive; nothing indicates the reef's species were in a resting state.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-interface", "wordId": "mh-interface", "skill": "words-in-context", "stem": "The designers of the new prosthetic limb concentrated on the ______ between nerve and machine: this crucial point of contact had to translate the body's faint electrical signals into smooth mechanical motion almost instantly.", "choices": [{"text": "obstacle", "why": "'Obstacle' means a barrier that blocks; the passage describes a working point of contact, not something impeding function.", "tag": "reversed"}, {"text": "residue", "why": "'Residue' is leftover matter; it has no bearing on where two systems meet and communicate.", "tag": "unsupported"}, {"text": "hierarchy", "why": "'Hierarchy' means a ranking of levels; the passage concerns connection between two systems, not their relative rank.", "tag": "unsupported"}, {"text": "interface", "why": "The 'point of contact' 'between nerve and machine' that must translate signals across systems is precisely an interface."}], "answer": 3},
{"id": "vq-mh-intermingled-with", "wordId": "mh-intermingled-with", "skill": "words-in-context", "stem": "In the old port city's markets, the traditions of a dozen cultures were so thoroughly ______ one another that Portuguese melodies drifted through Swahili chants and Arabic spices seasoned Indian recipes until no single origin could be untangled.", "choices": [{"text": "separated from", "why": "'Separated from' means kept apart, the reverse of traditions blended until they could not be untangled.", "tag": "reversed"}, {"text": "intermingled with", "why": "Cultures blended 'until no single origin could be untangled' describes traditions mixed and mingled together."}, {"text": "borrowed from", "why": "'Borrowed from' implies one tradition takes a feature while origins stay identifiable; the passage says the origins fused past recognition.", "tag": "too-specific"}, {"text": "ranked above", "why": "'Ranked above' asserts a hierarchy of prestige, which the passage of mutual fusion never establishes.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-intricate", "wordId": "mh-intricate", "skill": "words-in-context", "stem": "The clockmaker's masterpiece packed hundreds of gears, springs, and levers into a case no larger than a walnut; its ______ mechanism, with every part depending on the motion of another, astonished even seasoned engineers.", "choices": [{"text": "rudimentary", "why": "Rudimentary means basic or undeveloped, the opposite of a mechanism built from hundreds of interdependent parts.", "tag": "reversed"}, {"text": "intricate", "why": "The detail 'every part depending on the motion of another' names many interconnected elements, the defining sense of intricate."}, {"text": "ornate", "why": "Ornate stresses elaborate decoration rather than complex, interlocking structure, so it misses the point about interdependent parts.", "tag": "too-specific"}, {"text": "sturdy", "why": "Sturdy describes durability or strength, which the passage never raises.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-invoke", "wordId": "mh-invoke", "skill": "words-in-context", "stem": "To defend her unorthodox strategy, the attorney chose to ______ a centuries-old statute that everyone else in the courtroom had assumed was long forgotten, citing its exact wording to bolster her argument.", "choices": [{"text": "repeal", "why": "To repeal is to abolish a law, not to call upon it in support of an argument.", "tag": "reversed"}, {"text": "draft", "why": "To draft is to compose something new, whereas the attorney is calling on an existing statute.", "tag": "unsupported"}, {"text": "invoke", "why": "'Citing its exact wording to bolster her argument' shows she calls upon the statute for support—the meaning of invoke."}, {"text": "ratify", "why": "To ratify is to give formal approval to something, which is not what an attorney does with an old law in court.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-irreproachable", "wordId": "mh-irreproachable", "skill": "words-in-context", "stem": "Across four decades on the bench, the judge maintained a record so ______ that even her fiercest political opponents, who scrutinized every ruling for a hint of impropriety, could never find a single fault to exploit.", "choices": [{"text": "irreproachable", "why": "The clue that even hostile scrutineers 'could never find a single fault' points to a record that is entirely blameless—irreproachable."}, {"text": "commendable", "why": "Commendable means praiseworthy but still admits shortcomings; it falls short of the flawlessness the passage insists on.", "tag": "too-broad"}, {"text": "ambitious", "why": "Ambitious describes drive for success, which has nothing to do with being free of fault.", "tag": "unsupported"}, {"text": "questionable", "why": "Questionable means doubtful or suspect, the opposite of a record no critic could fault.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-lambaste", "wordId": "mh-lambaste", "skill": "words-in-context", "stem": "When the young playwright's debut finally opened, the reviewers did not merely find minor faults with it—they ______ it, condemning nearly every scene in language so scathing that the production shut down within a single week.", "choices": [{"text": "lambasted", "why": "'Condemning nearly every scene in language so scathing' describes harsh, severe criticism—exactly what lambasted means."}, {"text": "lauded", "why": "Lauded means praised highly, the reverse of scathing condemnation that closes a show.", "tag": "reversed"}, {"text": "analyzed", "why": "Analyzed suggests neutral, detailed examination, not the fierce attack the passage describes.", "tag": "unsupported"}, {"text": "critiqued", "why": "Critiqued means reviewed or evaluated and lacks the intensity of the brutal condemnation described here.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-mh-manifestation", "wordId": "mh-manifestation", "skill": "words-in-context", "stem": "Sociologists argue that fashion trends are rarely superficial; a sudden collective embrace of austere, minimal clothing, for instance, can be read as a visible ______ of deeper economic anxiety, an outward expression of feelings the public rarely states aloud.", "choices": [{"text": "catalyst", "why": "A catalyst is a cause that triggers something; here the anxiety causes the trend, so the direction is reversed.", "tag": "reversed"}, {"text": "anomaly", "why": "An anomaly is an irregularity or deviation; nothing marks the trend as abnormal.", "tag": "unsupported"}, {"text": "epitome", "why": "An epitome is the perfect embodiment of a type; that overstates and misses the passage's focus on outward expression.", "tag": "too-specific"}, {"text": "manifestation", "why": "The appositive 'an outward expression of feelings the public rarely states aloud' defines the blank precisely as a manifestation."}], "answer": 3},
{"id": "vq-mh-material-to", "wordId": "mh-material-to", "skill": "words-in-context", "stem": "The historian argued that the newly discovered letters were ______ any honest account of the treaty negotiations: without them, scholars had been overlooking the private doubts that shaped the final agreement.", "choices": [{"text": "peripheral to", "why": "Peripheral to means of marginal importance, the opposite of the significance the clue 'shaped the final agreement' establishes.", "tag": "reversed"}, {"text": "material to", "why": "'Without them, scholars had been overlooking the private doubts that shaped the agreement' shows the letters are relevant and significant, i.e., material to the account."}, {"text": "consistent with", "why": "Consistent with means in agreement with; the passage stresses importance, not whether the letters agree with the account.", "tag": "unsupported"}, {"text": "analogous to", "why": "Analogous to means similar or comparable to, which is the wrong kind of relation between the letters and the account.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-meager", "wordId": "mh-meager", "skill": "words-in-context", "stem": "Stranded by the early blizzard, the expedition survived for weeks on ______ rations: a few ounces of dried meat and a handful of biscuits had to sustain each member through days of grueling travel.", "choices": [{"text": "copious", "why": "Copious means plentiful and abundant, the opposite of the tiny quantities the colon lists.", "tag": "reversed"}, {"text": "negligible", "why": "Negligible means so small as to be unimportant, but these barely sufficient rations mattered greatly to survival.", "tag": "too-specific"}, {"text": "meager", "why": "'A few ounces... and a handful... had to sustain each member' for weeks signals scarce, inadequate supply, which is meager."}, {"text": "perishable", "why": "Perishable means prone to spoiling, which addresses freshness rather than the quantity the passage emphasizes.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-misanthropic", "wordId": "mh-misanthropic", "skill": "words-in-context", "stem": "The playwright's later protagonists grow increasingly ______: they withdraw from society, sneer at every act of kindness, and voice a bitter conviction that human beings are fundamentally selfish and beyond redemption.", "choices": [{"text": "benevolent", "why": "Benevolent means kindly and well-meaning toward others, the opposite of sneering contempt for humanity.", "tag": "reversed"}, {"text": "misanthropic", "why": "Withdrawing from society, sneering at kindness, and believing people are fundamentally selfish define the distrust of humanity that is misanthropic."}, {"text": "eccentric", "why": "Eccentric means merely unconventional or odd and says nothing about hating people.", "tag": "too-broad"}, {"text": "indifferent", "why": "Indifferent means apathetic or neutral, too weak for the active bitterness and contempt described.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-mh-mitigate", "wordId": "mh-mitigate", "skill": "words-in-context", "stem": "Coastal engineers plant dense mangrove forests along vulnerable shorelines not to stop storms altogether, an impossible goal, but to ______ their destructive force: the tangled roots absorb wave energy and blunt the worst of the flooding.", "choices": [{"text": "exacerbate", "why": "Exacerbate means to worsen, the opposite of absorbing wave energy and blunting the flooding.", "tag": "reversed"}, {"text": "preclude", "why": "Preclude means to prevent entirely, but the passage explicitly rules that out with 'not to stop storms altogether.'", "tag": "too-specific"}, {"text": "mitigate", "why": "The contrast 'not to stop storms... but to' plus 'absorb wave energy and blunt the worst' matches mitigate, to lessen or alleviate."}, {"text": "rationalize", "why": "Rationalize means to justify or explain away; it belongs to the domain of argument, not reducing physical harm.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-momentous", "wordId": "mh-momentous", "skill": "words-in-context", "stem": "Historians of science regard the 1919 eclipse expedition as a ______ event: by confirming Einstein's prediction that gravity bends light, it overturned centuries of Newtonian assumption and reshaped the course of physics.", "choices": [{"text": "inconsequential", "why": "Inconsequential means trivial and unimportant, the opposite of overturning centuries of assumption.", "tag": "reversed"}, {"text": "coincidental", "why": "Coincidental means occurring by chance; the passage emphasizes deliberate impact, not accident.", "tag": "unsupported"}, {"text": "conspicuous", "why": "Conspicuous means highly visible or noticeable, which is not the same as being historically important.", "tag": "unsupported"}, {"text": "momentous", "why": "'Overturned centuries of Newtonian assumption and reshaped the course of physics' marks the event as significant and important, i.e., momentous."}], "answer": 3},
{"id": "vq-mh-monetizing", "wordId": "mh-monetizing", "skill": "words-in-context", "stem": "Streaming platforms initially offered their libraries free of charge, but investors soon demanded a strategy for ______ the vast audiences they had attracted: turning millions of casual listeners into a reliable source of revenue through subscriptions and targeted ads.", "choices": [{"text": "monetizing", "why": "The colon's elaboration 'turning millions of casual listeners into a reliable source of revenue' is exactly monetizing, generating revenue from something."}, {"text": "cataloging", "why": "Cataloging means organizing items into an ordered list, which is unrelated to earning income from an audience.", "tag": "unsupported"}, {"text": "appraising", "why": "Appraising means assessing the value of something; evaluation is not the same as generating revenue.", "tag": "unsupported"}, {"text": "subsidizing", "why": "Subsidizing means funding something at a loss, the opposite of drawing revenue from the audience.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-myriad", "wordId": "mh-myriad", "skill": "words-in-context", "stem": "Peering through the new telescope, the astronomers were staggered by what earlier instruments had missed: where the old star charts showed only a scattering of points, the upgraded lens revealed ______ galaxies, too numerous to count, strewn across a patch of sky no wider than a thumbnail.", "choices": [{"text": "scarce", "why": "Scarce means few and hard to find, the opposite of galaxies too numerous to count.", "tag": "reversed"}, {"text": "discernible", "why": "Discernible means barely perceptible; it addresses visibility rather than the sheer number the clue names.", "tag": "unsupported"}, {"text": "uniform", "why": "Uniform means all identical, describing sameness rather than the quantity the passage emphasizes.", "tag": "unsupported"}, {"text": "myriad", "why": "The appositive 'too numerous to count, strewn across' establishes countless quantity, exactly myriad."}], "answer": 3},
{"id": "vq-mh-nebulous", "wordId": "mh-nebulous", "skill": "words-in-context", "stem": "In its earliest anthropological formulations, the concept of 'culture' was notoriously ______: scholars invoked the term constantly yet defined it so loosely that one 1952 survey catalogued more than 150 competing, often contradictory definitions.", "choices": [{"text": "nebulous", "why": "The colon supplies the clue—defined 'so loosely' that 150 contradictory definitions coexisted—so the blank must mean vague and ill-defined."}, {"text": "precise", "why": "Reversed: precise means exactly and clearly defined, the opposite of a term with 150 loose, contradictory definitions.", "tag": "reversed"}, {"text": "obscure", "why": "Obscure means little known, but the passage says scholars 'invoked the term constantly'—the concept was famous, just poorly defined.", "tag": "reversed"}, {"text": "obsolete", "why": "Obsolete means outdated and no longer in use; nothing in the passage suggests the concept had fallen out of use—quite the contrary.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-necessitate", "wordId": "mh-necessitate", "skill": "words-in-context", "stem": "Since no repair mission can reach the James Webb Space Telescope at its station nearly a million miles from Earth, any component failure after launch would ______ working around the damaged instrument permanently; engineers therefore subjected every part to exhaustive testing before liftoff.", "choices": [{"text": "preclude", "why": "Reversed: preclude means to prevent or rule out, but the impossibility of repair makes workarounds unavoidable, not impossible.", "tag": "reversed"}, {"text": "encourage", "why": "Too weak: encourage means to promote as one option among several, but with no repair possible, a workaround is the only option—compulsory, not merely favored.", "tag": "too-broad"}, {"text": "nullify", "why": "Nullify means to cancel or invalidate; a failure cannot invalidate the workaround that responds to it, and nothing in the passage involves canceling.", "tag": "unsupported"}, {"text": "necessitate", "why": "Because 'no repair mission can reach' the telescope, a failure would make workarounds required—necessitate captures that forced consequence."}], "answer": 3},
{"id": "vq-mh-notional", "wordId": "mh-notional", "skill": "words-in-context", "stem": "The city's pledge of carbon neutrality by 2040 remains largely ______: the goal appears in speeches and planning documents, but no budget, timeline, or enforcement mechanism yet exists to convert it into practice.", "choices": [{"text": "operational", "why": "Reversed: operational means actually functioning in practice, but the passage stresses that nothing yet exists 'to convert it into practice.'", "tag": "reversed"}, {"text": "ambitious", "why": "Ambitious describes the scale of a goal; the contrast here is between existing on paper and existing in practice, not between bold and timid aims.", "tag": "true-but-irrelevant"}, {"text": "unpopular", "why": "Unpopular means widely disliked; the passage says nothing about public opposition to the pledge.", "tag": "unsupported"}, {"text": "notional", "why": "A goal that exists only 'in speeches and planning documents' with no budget or mechanism is theoretical rather than real—notional."}], "answer": 3},
{"id": "vq-mh-novelty", "wordId": "mh-novelty", "skill": "words-in-context", "stem": "Consumer researchers find that a gadget's ______ can drive early sales but rarely sustains them: shoppers initially flock to devices unlike anything they have seen, yet that appeal evaporates once the products become commonplace.", "choices": [{"text": "ingenuity", "why": "Ingenuity means cleverness of design, which would not evaporate merely because a product becomes commonplace; the fading quality is unfamiliarity, not skill.", "tag": "true-but-irrelevant"}, {"text": "durability", "why": "Durability means ability to withstand wear; nothing in the passage concerns how long the gadgets last physically.", "tag": "unsupported"}, {"text": "novelty", "why": "The clues 'unlike anything they have seen' and appeal that fades 'once the products become commonplace' point to newness itself—novelty."}, {"text": "notoriety", "why": "Notoriety means fame for something bad; the passage describes attraction to unfamiliar devices, not a scandalous reputation.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-nullify", "wordId": "mh-nullify", "skill": "words-in-context", "stem": "In 1832, South Carolina asserted a state's power to ______ federal tariff acts within its borders, declaring them void and unenforceable; President Jackson countered that no single state could erase a law passed by Congress.", "choices": [{"text": "ratify", "why": "Reversed: ratify means to formally approve, but the state was declaring the acts 'void and unenforceable,' not endorsing them.", "tag": "reversed"}, {"text": "amend", "why": "Amend means to revise a law's wording; the passage describes wholesale invalidation—declaring the acts void—not editing them.", "tag": "unsupported"}, {"text": "suspend", "why": "Precision failure: suspend means to halt temporarily, but 'void and unenforceable' and Jackson's word 'erase' indicate permanent invalidation.", "tag": "too-specific"}, {"text": "nullify", "why": "The appositive clue 'declaring them void and unenforceable' defines the blank: to cancel a law's legal force is to nullify it."}], "answer": 3},
{"id": "vq-mh-obedient", "wordId": "mh-obedient", "skill": "words-in-context", "stem": "Sheepdog trials reward animals that are unfailingly ______: a champion border collie will abandon its own pursuit of a straying ewe the instant its handler whistles a contrary command, deferring wholly to the human's judgment.", "choices": [{"text": "independent", "why": "Reversed: independent means acting on one's own judgment, but the dog abandons its own pursuit and defers 'wholly to the human's judgment.'", "tag": "reversed"}, {"text": "obedient", "why": "The colon's example—instantly following a contrary command and 'deferring wholly' to the handler—defines compliance with authority: obedient."}, {"text": "clever", "why": "Clever means skilled at independent problem-solving; the passage prizes the dog for setting aside its own judgment, not for exercising it.", "tag": "true-but-irrelevant"}, {"text": "energetic", "why": "Energetic means full of vigor; nothing in the passage concerns stamina—the clue is about responding to commands.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-obliviousness", "wordId": "mh-obliviousness", "skill": "words-in-context", "stem": "Jane Austen draws much of her comedy from her characters' ______: Emma Woodhouse, for instance, busily arranges other people's marriages while remaining entirely unaware of the romantic attachments forming in front of her, including her own.", "choices": [{"text": "perceptiveness", "why": "Reversed: perceptiveness means keen awareness, but Emma remains 'entirely unaware' of what is happening in front of her.", "tag": "reversed"}, {"text": "indifference", "why": "Indifference means lack of concern; Emma is intensely invested in others' romances—her failure is one of perception, not of caring.", "tag": "unsupported"}, {"text": "obliviousness", "why": "The colon's example—Emma 'remaining entirely unaware' of attachments forming before her—directly glosses obliviousness, a failure to notice."}, {"text": "vanity", "why": "Vanity means excessive pride in oneself; even if true of Emma, pride does not explain her failing to notice the romances around her.", "tag": "true-but-irrelevant"}], "answer": 2},
{"id": "vq-mh-obscure", "wordId": "mh-obscure", "skill": "words-in-context", "stem": "Cuttlefish can ______ their outlines within seconds: by rippling shifting patterns of pigment across their skin, they blur the border between body and background until predators can no longer tell where the animal ends and the seafloor begins.", "choices": [{"text": "obscure", "why": "The colon explains the blank: blurring the border until predators 'can no longer tell where the animal ends' means hiding or concealing the outline—obscuring it."}, {"text": "reveal", "why": "Reversed: reveal means to make visible, but the pigment display makes the outline impossible for predators to detect.", "tag": "reversed"}, {"text": "darken", "why": "Too narrow: darken names one specific color change, but the clue is about making the outline indistinct, not making it darker.", "tag": "too-specific"}, {"text": "replicate", "why": "Replicate means to copy exactly; duplicating an outline is not the same as blurring it into the background, and nothing describes copying.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-omen", "wordId": "mh-omen", "skill": "words-in-context", "stem": "Roman augurs treated the natural world as a text to be deciphered: comets, lightning strikes, and the flight paths of birds were scrutinized as ______ of coming political fortune, powerful enough to delay elections or unnerve generals.", "choices": [{"text": "symptoms", "why": "Precision failure: symptoms are signs of a condition that already exists, but the passage concerns forecasts 'of coming political fortune.'", "tag": "too-specific"}, {"text": "causes", "why": "The augurs read these events as foretelling upheaval, not producing it; nothing suggests comets were thought to make political fortune happen.", "tag": "unsupported"}, {"text": "remnants", "why": "Reversed in time: remnants are leftover traces of the past, but the events were read as pointing toward what was 'coming.'", "tag": "reversed"}, {"text": "omens", "why": "Natural events 'scrutinized as' signs 'of coming political fortune' are prophetic warnings—omens."}], "answer": 3},
{"id": "vq-mh-opaque", "wordId": "mh-opaque", "skill": "words-in-context", "stem": "Critics of the regulatory agency complained that its rulemaking process was ______: decisions emerged from closed-door sessions without published rationales, leaving even seasoned observers unable to explain why one proposal advanced while a nearly identical one failed.", "choices": [{"text": "transparent", "why": "Reversed: transparent means open and easy to understand, but the colon elaborates a process no one can see into or explain.", "tag": "reversed"}, {"text": "meticulous", "why": "Meticulous means extremely careful about details; the passage criticizes the process's secrecy and unexplainability, not its level of care.", "tag": "unsupported"}, {"text": "opaque", "why": "The colon introduces the elaboration — closed-door sessions, no published rationales, observers 'unable to explain' outcomes — so the blank must mean impossible to see through or understand."}, {"text": "outmoded", "why": "Outmoded means old-fashioned or obsolete; nothing in the passage concerns the process being out of date, only its being hidden and inscrutable.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-orthodox", "wordId": "mh-orthodox", "skill": "words-in-context", "stem": "Rather than embrace the experimental pedagogies gaining favor elsewhere, the conservatory's faculty maintained a defiantly ______ curriculum, assigning the same sequence of scale exercises and counterpoint drills that instructors have required of students for more than a century.", "choices": [{"text": "innovative", "why": "Reversed: innovative means introducing new methods — exactly the 'experimental pedagogies' the faculty refuses to embrace.", "tag": "reversed"}, {"text": "rigorous", "why": "The drills may well be demanding, but the contrast is between experimental methods and ones unchanged 'for more than a century' — a claim about tradition, not difficulty.", "tag": "true-but-irrelevant"}, {"text": "orthodox", "why": "The contrast with 'experimental pedagogies' plus the clue that the same drills have been required for over a century selects a word meaning conventional and traditional."}, {"text": "esoteric", "why": "Esoteric means understood by only a small, specialized circle; the passage describes standard, long-established exercises, not obscure or secret knowledge.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-oscillate", "wordId": "mh-oscillate", "skill": "words-in-context", "stem": "Polling analysts observed that public sentiment toward the referendum did not move steadily in either direction; instead, support continued to ______ throughout the campaign, climbing after each televised debate and slipping back within weeks.", "choices": [{"text": "oscillate", "why": "The clue 'climbing... and slipping back' after the analysts rule out steady movement in 'either direction' describes a repeated back-and-forth swing — precisely to oscillate."}, {"text": "escalate", "why": "Reversed: escalate means to increase steadily, but the passage explicitly denies steady movement and notes that support kept slipping back.", "tag": "reversed"}, {"text": "consolidate", "why": "Consolidate means to become firm and stable; nothing supports settling into stability — the numbers kept swinging up and down.", "tag": "unsupported"}, {"text": "dissipate", "why": "Dissipate means to fade away entirely; the passage says support repeatedly climbed as well as slipped, so it did not simply drain away.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-outmode", "wordId": "mh-outmode", "skill": "words-in-context", "stem": "Historians of computing emphasize that the transistor did not merely improve upon the vacuum tube; it threatened to ______ the older component altogether, rendering tube-based circuits unfit for the compact devices consumers soon demanded.", "choices": [{"text": "refine", "why": "Reversed: refine means to improve gradually — precisely what the contrast 'did not merely improve upon' rules out for the blank.", "tag": "reversed"}, {"text": "miniaturize", "why": "Compactness motivates the shift, but the blank describes what the transistor did to the vacuum tube — rendered it unfit for use — not an act of shrinking it.", "tag": "true-but-irrelevant"}, {"text": "replicate", "why": "Replicate means to copy or reproduce; nothing suggests the transistor duplicated the tube — it displaced it.", "tag": "unsupported"}, {"text": "outmode", "why": "The result clause 'rendering tube-based circuits unfit' shows the transistor made the older component obsolete, which is exactly what outmode means."}], "answer": 3},
{"id": "vq-mh-outmoded", "wordId": "mh-outmoded", "skill": "words-in-context", "stem": "Veteran navigators still praise the elegance of printed nautical charts, yet most now concede that such charts are ______: once the industry standard, they have been superseded by satellite systems that update hazard information in real time.", "choices": [{"text": "indispensable", "why": "Reversed: indispensable means impossible to do without, but the colon explains that the charts have been superseded by newer systems.", "tag": "reversed"}, {"text": "outmoded", "why": "The colon's gloss — 'once the industry standard... superseded by' newer technology — defines the blank as outdated, which is what outmoded means."}, {"text": "ornamental", "why": "The navigators' praise of the charts' elegance is real but beside the point; the concession introduced by 'yet' concerns the charts being superseded, not their being merely decorative.", "tag": "true-but-irrelevant"}, {"text": "defective", "why": "Defective means faulty or broken; the charts are described as overtaken by better technology, not as malfunctioning.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-outspoken", "wordId": "mh-outspoken", "skill": "words-in-context", "stem": "Journalist Ida B. Wells was famously ______ in her opposition to mob violence: her editorials named perpetrators directly and condemned complicit officials in blunt terms, even when such candor put her own safety at risk.", "choices": [{"text": "diplomatic", "why": "Reversed: diplomatic means tactful and indirect, the opposite of naming perpetrators directly and condemning officials in blunt terms.", "tag": "reversed"}, {"text": "eloquent", "why": "Wells's prose may have been eloquent, but the colon's clues — direct naming, blunt terms, risky candor — concern her frankness, not the polish of her style.", "tag": "true-but-irrelevant"}, {"text": "outspoken", "why": "The colon elaborates the blank: naming wrongdoers 'directly,' condemning 'in blunt terms,' and risking safety through 'candor' all define a frank, vocal critic."}, {"text": "impartial", "why": "Impartial means taking no side; the passage presents Wells as an emphatic opponent of mob violence, not a neutral observer.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-outstrip", "wordId": "mh-outstrip", "skill": "words-in-context", "stem": "University administrators warn that if enrollment continues to ______ the institution's capacity to hire qualified instructors, seminar-style courses will give way to crowded lecture halls within a decade.", "choices": [{"text": "outstrip", "why": "The predicted consequence — crowded lecture halls replacing seminars — follows only if student numbers exceed hiring capacity, so the blank must mean surpass."}, {"text": "rival", "why": "Too weak: rival means to come close to equaling, but mere parity between enrollment and hiring would not produce the overcrowding the administrators predict.", "tag": "too-specific"}, {"text": "trail", "why": "Reversed: if enrollment trailed hiring capacity, classes would shrink rather than swell into crowded lecture halls.", "tag": "reversed"}, {"text": "mirror", "why": "Mirror means to match exactly; nothing supports enrollment and capacity staying in balance — the warning depends on a growing gap between them.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-overshadow", "wordId": "mh-overshadow", "skill": "words-in-context", "stem": "Conductors sometimes worry that a celebrated touring soloist will ______ the resident orchestra, monopolizing the audience's attention so thoroughly that the ensemble's own artistry goes unnoticed in reviews.", "choices": [{"text": "complement", "why": "Reversed: complement means to enhance by combining well with, but the worry is that the ensemble's artistry 'goes unnoticed,' not that it is set off to advantage.", "tag": "reversed"}, {"text": "overshadow", "why": "'Monopolizing the audience's attention' so that the orchestra 'goes unnoticed' defines the blank: the soloist outshines and dominates the ensemble."}, {"text": "accompany", "why": "Orchestras and soloists do perform together, but accompany merely means to perform alongside; it cannot explain why the ensemble would go unnoticed.", "tag": "true-but-irrelevant"}, {"text": "emulate", "why": "Emulate means to imitate in hopes of equaling; nothing suggests the soloist copies the orchestra — the issue is stolen attention.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-mh-paradox", "wordId": "mh-paradox", "skill": "words-in-context", "stem": "Economists have long puzzled over a seeming ______ in survey data: as nations grow wealthier, average reported happiness often fails to rise, yet within any single country, richer citizens consistently report greater life satisfaction than poorer ones.", "choices": [{"text": "consensus", "why": "Consensus means general agreement; the economists are described as puzzled by conflicting findings, not as having settled on a shared view.", "tag": "unsupported"}, {"text": "correlation", "why": "An association does appear within countries, but the blank must name the apparent contradiction between the two findings — the very thing that makes economists puzzle.", "tag": "true-but-irrelevant"}, {"text": "paradox", "why": "The two findings joined by 'yet' contradict each other — wealth predicts happiness within nations but not across time — and 'puzzled' plus 'seeming' signal an apparent inconsistency, i.e., a paradox."}, {"text": "redundancy", "why": "Redundancy means needless repetition; the two findings are not duplicates but opposites in implication.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-partitioned", "wordId": "mh-partitioned", "skill": "words-in-context", "stem": "Excavations of the ancient villa revealed that its single great hall had once been ______ by movable wooden screens, for archaeologists found grooves worn into the floor marking where the space had been split into separate chambers for different household activities.", "choices": [{"text": "partitioned", "why": "'Split into separate chambers' and the floor grooves marking dividers make the blank mean divided into sections, which is exactly what partitioned denotes."}, {"text": "consolidated", "why": "Consolidated means merged into one whole, the reverse of a hall broken into separate chambers.", "tag": "reversed"}, {"text": "excavated", "why": "Excavated means dug out of the earth; it describes the archaeologists' activity, not what was done to the hall's interior space.", "tag": "true-but-irrelevant"}, {"text": "fortified", "why": "Fortified means strengthened against attack; nothing in the passage concerns defense or reinforcement.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-mh-paucity", "wordId": "mh-paucity", "skill": "words-in-context", "stem": "Because deep-sea vents lie far beyond the reach of sunlight, the ______ of photosynthetic organisms there once puzzled biologists, who could not explain how any life at all endured on so little available energy.", "choices": [{"text": "abundance", "why": "Abundance means a plentiful supply, the opposite of the shortage implied by 'so little available energy.'", "tag": "reversed"}, {"text": "paucity", "why": "'Beyond the reach of sunlight' and 'so little available energy' establish a severe shortage, which is exactly what paucity names."}, {"text": "diversity", "why": "Diversity refers to variety of kinds, but the clue is about how few organisms there are, not how varied they are.", "tag": "unsupported"}, {"text": "proliferation", "why": "Proliferation means rapid multiplication and increase, the reverse of the scarcity the passage describes.", "tag": "reversed"}], "answer": 1},
{"id": "vq-mh-perceptible", "wordId": "mh-perceptible", "skill": "words-in-context", "stem": "When conservators finished cleaning the centuries-old fresco, the treatment produced a faint but clearly ______ brightening of the pigments: even from across the gallery, trained observers could detect the difference at once.", "choices": [{"text": "negligible", "why": "Negligible means too slight to notice, contradicting 'observers could detect the difference at once.'", "tag": "reversed"}, {"text": "permanent", "why": "Permanent concerns duration, but the clue is about whether the brightening can be seen, not how long it lasts.", "tag": "unsupported"}, {"text": "gradual", "why": "Gradual describes the pace of a change; the passage stresses that the change is visible, not how slowly it occurred.", "tag": "true-but-irrelevant"}, {"text": "perceptible", "why": "'Trained observers could detect the difference at once, even from across the gallery' shows the change is noticeable, which is what perceptible means."}], "answer": 3},
{"id": "vq-mh-perturbation", "wordId": "mh-perturbation", "skill": "words-in-context", "stem": "Astronomers first inferred the existence of Neptune not by seeing it but by noticing a slight ______ in the orbit of Uranus: some unseen mass was evidently tugging the planet away from the path that Newtonian calculations had predicted.", "choices": [{"text": "constancy", "why": "Constancy means steadiness and lack of change, the reverse of an orbit being pulled off its predicted path.", "tag": "reversed"}, {"text": "acceleration", "why": "Acceleration names one specific kind of change; the passage indicates only that the orbit deviated, not that the planet sped up.", "tag": "too-specific"}, {"text": "symmetry", "why": "Symmetry refers to balanced correspondence of parts and has no bearing on a deviation from a calculated orbit.", "tag": "unsupported"}, {"text": "perturbation", "why": "'Tugging the planet away from the path Newtonian calculations had predicted' describes a disturbance to the orbit, which is exactly what perturbation means."}], "answer": 3},
{"id": "vq-mh-pervade", "wordId": "mh-pervade", "skill": "words-in-context", "stem": "A faint scent of woodsmoke seemed to ______ every corner of the old inn; guests remarked on it in the dining hall, in the bedrooms, and even in the freshly laundered linens, as if nothing in the building could escape it.", "choices": [{"text": "pervade", "why": "The scent being present 'in the dining hall, in the bedrooms, and even in the linens' with 'nothing could escape it' shows it spreads throughout, which pervade means."}, {"text": "evade", "why": "Evade means to escape or elude; it inverts the idea that the scent reaches everywhere, and echoes 'escape' as a trap.", "tag": "reversed"}, {"text": "dominate", "why": "Dominate means to control or overpower; the passage stresses that the scent is diffused everywhere, not that it overwhelms the senses.", "tag": "unsupported"}, {"text": "dissipate", "why": "Dissipate means to scatter and fade away, the reverse of a scent lingering in every room.", "tag": "reversed"}], "answer": 0},
{"id": "vq-mh-placate", "wordId": "mh-placate", "skill": "words-in-context", "stem": "Faced with mounting protests over the new tax, the governor offered a series of concessions intended to ______ the crowds: he suspended the levy, ordered the release of those who had been arrested, and promised to hear their grievances in person.", "choices": [{"text": "provoke", "why": "Provoke means to stir up anger, the reverse of the soothing effect the governor's concessions were meant to have.", "tag": "reversed"}, {"text": "mobilize", "why": "Mobilize means to rally people into action; the governor wanted to quiet the crowds, not organize them.", "tag": "reversed"}, {"text": "placate", "why": "Suspending the tax, freeing prisoners, and promising to hear grievances are all measures meant to calm angry crowds, which is what placate means."}, {"text": "disperse", "why": "Disperse means to scatter a crowd physically; the concessions aim to ease the crowds' anger, not to drive them apart.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-mh-postulate", "wordId": "mh-postulate", "skill": "words-in-context", "stem": "Long before atoms could be observed by any instrument, Dalton found it useful to ______ that all matter is composed of tiny indivisible particles; from this unproven assumption he was then able to derive the laws of chemical combination.", "choices": [{"text": "verify", "why": "Verify means to confirm with evidence, impossible here since atoms 'could not be observed' and the idea is called 'unproven.'", "tag": "reversed"}, {"text": "refute", "why": "Refute means to disprove, the reverse of adopting the idea as a starting premise for further reasoning.", "tag": "reversed"}, {"text": "demonstrate", "why": "Demonstrate means to prove conclusively, contradicting the passage's explicit label 'unproven assumption.'", "tag": "reversed"}, {"text": "postulate", "why": "Assuming an unproven idea as the basis from which laws are then derived is exactly what postulate means: to propose something as a foundation for reasoning."}], "answer": 3},
{"id": "vq-mh-precede", "wordId": "mh-precede", "skill": "words-in-context", "stem": "In the traditional concert program, a short orchestral overture is meant to ______ the main symphony, easing the audience gently into the evening before the principal work of the night begins.", "choices": [{"text": "follow", "why": "Follow means to come after, the reverse of an overture that plays before the main symphony.", "tag": "reversed"}, {"text": "interrupt", "why": "Interrupt means to break into something already under way; the overture comes first, in an orderly sequence.", "tag": "unsupported"}, {"text": "precede", "why": "'Easing the audience in before the principal work begins' shows the overture comes before the symphony, which is exactly what precede means."}, {"text": "replace", "why": "Replace means to take the place of; the symphony still occurs, with the overture simply leading into it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-mh-preceded", "wordId": "mh-preceded", "skill": "words-in-context", "stem": "Geologists have established that a long stretch of intense volcanic activity ______ the mass extinction, filling the atmosphere with ash and gases for many thousands of years before the great die-off of species finally began.", "choices": [{"text": "followed", "why": "Followed means came after, the reverse of activity occurring 'for many thousands of years before' the die-off began.", "tag": "reversed"}, {"text": "accompanied", "why": "Accompanied means happened at the same time, but the passage places the volcanism before the extinction, not alongside it.", "tag": "too-specific"}, {"text": "triggered", "why": "Triggered asserts causation, which is tempting, but the clue 'before the great die-off began' marks time order, not cause.", "tag": "true-but-irrelevant"}, {"text": "preceded", "why": "'For many thousands of years before the great die-off began' establishes that the volcanic activity came before the extinction, which is what preceded means."}], "answer": 3}
);
